/* Jetons BEA DIGITAL = palette des graphiques immo (CHART_COLORS). */

:root {
  --bea-brand-900: #1a5278;
  --bea-brand-800: #21618c;
  --bea-brand-700: #2874a6;
  --bea-brand-600: #3498db;
  --bea-brand-400: #5dade2;
  --bea-surface: #eef2f6;
  --bea-surface-card: #ffffff;
  --bea-ink: #0f172a;
  --bea-ink-muted: #475569;
  --bea-line: #e8eef4;
  --bea-chip: #dbeafe;
  --bea-chip-ink: #2874a6;
  --bea-bar: #bfdbfe;
  --bea-bar-max: #2874a6;
  --bea-ok-bg: #dcfce7;
  --bea-ok-ink: #15803d;
  --bea-warn-bg: #fff7ed;
  --bea-warn-ink: #c2410c;
  --bea-danger-ink: #b91c1c;
}

bea-chrome {
  display: block;
}

.bea-chrome {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  min-height: 4rem;
  padding: 0.75rem 1.5rem;
  background: linear-gradient(90deg, #1a5278 0%, #0f172a 72%);
  color: #fff;
  border-bottom: 1px solid rgb(255 255 255 / 0.08);
}

.bea-chrome__brand {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  color: inherit;
  text-decoration: none;
  min-width: 0;
}

.bea-chrome__logo {
  width: 2.35rem;
  height: 2.35rem;
  object-fit: contain;
  flex-shrink: 0;
}

.bea-chrome__name {
  font-size: 1.05rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  line-height: 1.15;
}

.bea-chrome__sub {
  margin-top: 0.1rem;
  font-size: 0.72rem;
  color: rgb(226 232 240 / 0.7);
  letter-spacing: 0.02em;
}

.bea-chrome__actions {
  display: flex;
  align-items: center;
  gap: 0.85rem;
  flex-shrink: 0;
}

.bea-chrome__userchip {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  min-width: 0;
}

.bea-chrome__avatar {
  display: grid;
  place-items: center;
  width: 1.85rem;
  height: 1.85rem;
  flex-shrink: 0;
  color: #dbeafe;
}

.bea-chrome__avatar svg {
  width: 1.2rem;
  height: 1.2rem;
}

.bea-chrome__user {
  font-size: 0.8125rem;
  font-weight: 600;
  max-width: 14rem;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.bea-chrome__logout {
  appearance: none;
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  border: 1px solid rgb(94 184 240 / 0.55);
  background: transparent;
  color: #fff;
  font: inherit;
  font-size: 0.8125rem;
  font-weight: 600;
  padding: 0.35rem 0.8rem;
  border-radius: 999px;
  cursor: pointer;
}

.bea-chrome__logout svg {
  width: 0.95rem;
  height: 0.95rem;
}

.bea-chrome__logout:hover {
  background: rgb(219 234 254 / 0.14);
  border-color: #5dade2;
}

bea-fil-ariane {
  display: block;
  height: 2.5rem;
}

.bea-fil-ariane {
  height: 2.5rem;
  display: flex;
  align-items: center;
  padding: 0 1.5rem;
  background: #f1f5f9;
  border-bottom: 1px solid #e2e8f0;
  box-sizing: border-box;
}

.bea-fil-ariane__list {
  display: flex;
  flex-wrap: nowrap;
  align-items: center;
  gap: 0.35rem;
  margin: 0;
  padding: 0;
  list-style: none;
  overflow: hidden;
  min-width: 0;
}

.bea-fil-ariane__item {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  min-width: 0;
  font-size: 0.8125rem;
  font-weight: 600;
  color: #64748b;
}

.bea-fil-ariane__item a {
  color: #2874a6;
  text-decoration: none;
  white-space: nowrap;
}

.bea-fil-ariane__item a:hover {
  text-decoration: underline;
}

.bea-fil-ariane__item span[aria-current='page'] {
  color: #0f172a;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.bea-fil-ariane__sep {
  color: #94a3b8;
  font-weight: 700;
}

.bea-plateforme {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  background: #f3f7fb;
  color: #0f172a;
}

.bea-plateforme__body {
  flex: 1;
  width: 100%;
  max-width: 72rem;
  margin: 0 auto;
  padding: 1.75rem 1.5rem 2.5rem;
}

.bea-plateforme__body.bea-hub {
  max-width: none;
  width: 100%;
  padding: 1.25rem clamp(1.25rem, 2.5vw, 2.75rem) 1.75rem;
}

.bea-hub .bea-plateforme__lead {
  max-width: none;
  margin-bottom: 0.85rem;
}

.bea-hub .bea-card-grid {
  grid-template-columns: repeat(auto-fill, minmax(17.5rem, 1fr));
  gap: 1rem;
}

@media (min-width: 1280px) {
  .bea-hub .bea-card-grid {
    grid-template-columns: repeat(auto-fill, minmax(19rem, 1fr));
  }

  .bea-hub__kpis {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .bea-hub__columns {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (min-width: 1600px) {
  .bea-hub .bea-card-grid {
    grid-template-columns: repeat(5, minmax(0, 1fr));
  }
}

.bea-plateforme__kicker {
  margin: 0 0 0.2rem;
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #2874a6;
}

.bea-plateforme__title {
  margin: 0;
  font-size: 1.7rem;
  font-weight: 700;
  letter-spacing: -0.03em;
  color: #0f172a;
}

.bea-plateforme__lead {
  margin: 0.35rem 0 1.5rem;
  max-width: 42rem;
  font-size: 0.9375rem;
  font-weight: 500;
  line-height: 1.5;
  color: #334155;
}

.bea-card-grid {
  display: grid;
  grid-template-columns: repeat(1, minmax(0, 1fr));
  gap: 1.15rem;
}

@media (min-width: 720px) {
  .bea-card-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (min-width: 1100px) {
  .bea-card-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

/* Cartes = dash-charts__card (blanc, rayon 1rem, bordure #e8eef4). */
.bea-card {
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
  padding: 1.35rem 1.4rem 1.2rem;
  background: #fff;
  border: 1px solid #e8eef4;
  border-radius: 1rem;
  box-shadow: 0 8px 24px rgb(15 23 42 / 0.04);
  text-decoration: none;
  color: inherit;
  position: relative;
  overflow: hidden;
}

.bea-card--actif {
  transition: translate 0.28s ease, box-shadow 0.28s ease, border-color 0.28s ease;
}

.bea-card--actif:hover {
  translate: 0 -4px;
  border-color: #dbeafe;
  box-shadow: 0 8px 24px rgb(40 116 166 / 0.12);
}

.bea-espace__meta {
  margin: 0.35rem 0 0;
  font-size: 0.8125rem;
  font-weight: 600;
  color: #64748b;
}

/* Dashboard Global (hub Accueil) */
.bea-hub__welcome {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 1rem;
}

.bea-hub__core {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.55rem;
  align-self: flex-start;
  margin-top: 0.15rem;
  min-height: 3.15rem;
  padding: 0.85rem 1.45rem;
  border: 0;
  border-radius: 0.65rem;
  background: #1c6eab;
  color: #fff;
  font-size: 0.84rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  line-height: 1;
  text-decoration: none;
  white-space: nowrap;
  box-shadow: 0 8px 18px rgb(28 110 171 / 0.22);
  transition:
    translate 0.28s cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 0.28s ease,
    background 0.28s ease,
    scale 0.16s ease;
}

.bea-hub__core svg {
  width: 1.2rem;
  height: 1.2rem;
  flex-shrink: 0;
  transition: transform 0.45s cubic-bezier(0.22, 1, 0.36, 1);
}

.bea-hub__core:hover {
  translate: 0 -3px;
  background: #185f96;
  box-shadow: 0 14px 26px rgb(28 110 171 / 0.32);
}

.bea-hub__core:hover svg {
  transform: rotate(72deg);
}

.bea-hub__core:active {
  translate: 0 -1px;
  scale: 0.98;
}

.bea-hub__core:focus-visible {
  outline: 2px solid #1a5278;
  outline-offset: 3px;
}

@media (prefers-reduced-motion: reduce) {
  .bea-hub__core,
  .bea-hub__core svg {
    transition: none;
  }

  .bea-hub__core:hover,
  .bea-hub__core:active {
    translate: none;
    scale: none;
  }

  .bea-hub__core:hover svg {
    transform: none;
  }
}

.bea-hub__kpis {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.85rem;
  margin-bottom: 1.1rem;
}

.bea-hub__kpis[data-count='4'] {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.bea-hub__kpis[data-count='6'] {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.bea-hub .bea-card {
  min-height: 12.5rem;
  padding: 1.45rem 1.45rem 1.3rem;
}

.bea-hub__kpi {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  padding: 1.1rem 1.15rem;
  border-radius: 0.85rem;
  border: 1px solid #e8eef4;
  background: linear-gradient(180deg, #f8fbff 0%, #fff 70%);
  animation: bea-espace-rise 0.45s ease both;
}

.bea-hub__kpi span {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: #64748b;
}

.bea-hub__kpi strong {
  font-size: 1.7rem;
  font-weight: 700;
  letter-spacing: -0.03em;
  color: #1a5278;
}

.bea-hub__kpi em {
  font-style: normal;
  font-size: 0.75rem;
  line-height: 1.35;
  color: #94a3b8;
}

.bea-hub__section {
  margin-bottom: 1.1rem;
}

.bea-hub--dept {
  display: flex;
  flex-direction: column;
  max-width: 78rem;
  margin-inline: auto;
  width: 100%;
}

.bea-hub--dept .bea-hub__welcome {
  margin-bottom: 0.85rem;
}

.bea-hub--dept .bea-hub__kpis--compact {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 11.5rem));
  gap: 0.75rem;
  margin: 0 auto 1.15rem;
  width: fit-content;
  max-width: 100%;
}

.bea-hub--dept .bea-hub__kpi {
  padding: 0.8rem 0.95rem;
  min-width: 0;
}

.bea-hub--dept .bea-hub__kpi strong {
  font-size: 1.45rem;
}

.bea-hub--dept .bea-hub__section--fill {
  margin-bottom: 0;
}

.bea-hub--dept .bea-hub__section-head {
  text-align: center;
  margin-bottom: 0.85rem;
}

.bea-hub--dept .bea-card-grid--modules {
  grid-template-columns: repeat(auto-fit, minmax(15.5rem, 1fr));
  gap: 0.95rem;
}

.bea-hub--dept .bea-card {
  min-height: 13.5rem;
  height: auto;
  padding: 1.25rem 1.25rem 1.1rem;
}

.bea-hub--dept .bea-card__head {
  align-items: flex-start;
}

.bea-hub--dept .bea-card__title {
  font-size: 1.05rem;
  line-height: 1.3;
}

.bea-hub--dept .bea-card__text {
  margin: 0.15rem 0 0;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.bea-hub--dept .bea-card__meta {
  margin: 0.35rem 0 0;
  font-size: 0.78rem;
  font-weight: 600;
  color: #64748b;
}

.bea-hub--dept .bea-card__cta {
  margin-top: 0.55rem;
}

.bea-hub--dept .bea-card__viz {
  margin-top: auto;
  min-height: 0;
}

@media (min-width: 1200px) {
  .bea-hub--dept .bea-card-grid--modules {
    grid-template-columns: repeat(5, minmax(0, 1fr));
  }
}

/* Hub département avec domaines (ex. Audit, Contrôle & Conformité). */
.bea-dept-head {
  align-items: center;
}

.bea-dept-head__emblem {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 3.5rem;
  height: 3.5rem;
  border-radius: 1rem;
  color: #fff;
  background: linear-gradient(145deg, #1a5278 0%, #2874a6 100%);
  box-shadow: 0 10px 24px rgb(26 82 120 / 0.25);
}

.bea-dept-head__emblem .material-icons {
  font-size: 1.9rem;
}

.bea-dept-head__copy {
  flex: 1;
  min-width: 14rem;
}

.bea-dept-head__text {
  margin: 0.3rem 0 0;
  max-width: 46rem;
  font-size: 0.9rem;
  line-height: 1.5;
  color: #475569;
}

.bea-dom-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(17rem, 1fr));
  grid-auto-flow: dense;
  gap: 0.95rem;
}

.bea-dom {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  padding: 1.15rem 1.2rem;
  background: #fff;
  border: 1px solid #e8eef4;
  border-radius: 1rem;
  box-shadow: 0 8px 24px rgb(15 23 42 / 0.04);
}

/* Domaine qui porte des modules : pleine largeur, accent bleu BEA. */
.bea-dom--peuple {
  grid-column: 1 / -1;
  border-color: #dbeafe;
  background: linear-gradient(180deg, #f5f9fd 0%, #fff 60%);
}

.bea-dom--attente {
  opacity: 0.86;
}

.bea-dom__head,
.bea-dom__sub-head {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
}

.bea-dom__titles {
  flex: 1;
  min-width: 0;
}

.bea-dom__icon,
.bea-dom__sub-icon,
.bea-card__icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  border-radius: 0.7rem;
  color: #1a5278;
  background: #dbeafe;
}

.bea-dom__icon {
  width: 2.6rem;
  height: 2.6rem;
}

.bea-dom__sub-icon,
.bea-card__icon {
  width: 2.1rem;
  height: 2.1rem;
}

.bea-dom__sub-icon .material-icons,
.bea-card__icon .material-icons {
  font-size: 1.2rem;
}

.bea-dom--attente .bea-dom__icon {
  color: #64748b;
  background: #f1f5f9;
}

.bea-dom__title {
  margin: 0;
  font-size: 1.02rem;
  font-weight: 700;
  color: #0f172a;
}

.bea-dom__sub-title {
  margin: 0;
  font-size: 0.98rem;
  font-weight: 700;
  color: #0f172a;
}

.bea-dom__text {
  margin: 0.2rem 0 0;
  font-size: 0.85rem;
  line-height: 1.45;
  color: #64748b;
}

.bea-dom__wait {
  margin: 0;
  padding: 0.55rem 0.7rem;
  font-size: 0.8125rem;
  font-weight: 600;
  color: #64748b;
  background: #f8fafc;
  border: 1px dashed #cbd5e1;
  border-radius: 0.6rem;
}

.bea-dom__sub {
  display: flex;
  flex-direction: column;
  gap: 0.7rem;
  padding: 0.9rem 0.95rem;
  border: 1px solid #e8eef4;
  border-left: 3px solid #2874a6;
  border-radius: 0.8rem;
  background: #fff;
}

.bea-dom__later {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.bea-dom__later-list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(15rem, 1fr));
  gap: 0.5rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.bea-dom__later-item {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  padding: 0.55rem 0.7rem;
  font-size: 0.875rem;
  font-weight: 600;
  color: #334155;
  background: #f8fafc;
  border: 1px solid #e8eef4;
  border-radius: 0.6rem;
}

.bea-dom__later-item .material-icons {
  font-size: 1.15rem;
  color: #64748b;
}

.bea-dom__later-item > span:not(.bea-badge) {
  flex: 1;
  min-width: 0;
}

.bea-hub--dept .bea-dom__modules {
  grid-template-columns: repeat(auto-fill, minmax(16rem, 22rem));
}

@media (max-width: 900px) {
  .bea-hub--dept .bea-hub__kpis--compact {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    width: 100%;
  }

  .bea-hub--dept .bea-hub__section-head {
    text-align: left;
  }
}

.bea-hub__section-head {
  margin-bottom: 0.85rem;
}

.bea-hub__section-head h2 {
  margin: 0 0 0.2rem;
  font-size: 1.15rem;
  font-weight: 700;
  color: #0f172a;
}

.bea-hub__section-head p {
  margin: 0;
  font-size: 0.875rem;
  color: #64748b;
}

.bea-hub__columns {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.9rem;
  margin-bottom: 1rem;
}

.bea-hub__columns--solo {
  grid-template-columns: 1fr;
}

.bea-hub__columns .bea-hub__panel {
  display: flex;
  flex-direction: column;
  min-height: 0;
}

.bea-hub__columns .bea-hub__list {
  max-height: 16rem;
  overflow: auto;
  padding-right: 0.15rem;
}

.bea-hub__tips {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.7rem;
  counter-reset: bea-tip;
}

.bea-hub__tips li {
  position: relative;
  display: grid;
  gap: 0.2rem;
  padding: 0.75rem 0.85rem 0.75rem 2.6rem;
  border-radius: 0.65rem;
  border: 1px solid #e8eef4;
  background: #f8fbff;
  counter-increment: bea-tip;
}

.bea-hub__tips li::before {
  content: counter(bea-tip);
  position: absolute;
  left: 0.75rem;
  top: 0.8rem;
  display: grid;
  place-items: center;
  width: 1.35rem;
  height: 1.35rem;
  border-radius: 50%;
  background: #1a5278;
  color: #fff;
  font-size: 0.72rem;
  font-weight: 700;
}

.bea-hub__tips strong {
  font-size: 0.9rem;
  font-weight: 700;
  color: #0f172a;
}

.bea-hub__tips span {
  font-size: 0.82rem;
  line-height: 1.45;
  color: #64748b;
}

.bea-hub__panel {
  padding: 1rem 1.05rem;
  border-radius: 0.9rem;
  border: 1px solid #e8eef4;
  background: #fff;
  animation: bea-espace-rise 0.45s ease both;
}

.bea-hub__empty {
  margin: 0;
  font-size: 0.9rem;
  color: #64748b;
}

.bea-hub__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
}

.bea-hub__list a,
.bea-hub__list > li > div {
  display: grid;
  gap: 0.15rem;
  padding: 0.7rem 0.75rem;
  border-radius: 0.65rem;
  border: 1px solid #e8eef4;
  background: #f8fafc;
  text-decoration: none;
  color: inherit;
  transition: border-color 0.18s ease, background 0.18s ease;
}

.bea-hub__list a:hover {
  border-color: #bfdbfe;
  background: #eff6ff;
}

.bea-hub__list strong {
  font-size: 0.92rem;
  color: #0f172a;
}

.bea-hub__list span,
.bea-hub__list time {
  font-size: 0.8rem;
  color: #64748b;
}

.bea-hub__list em {
  justify-self: start;
  font-style: normal;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  padding: 0.15rem 0.45rem;
  border-radius: 999px;
  color: #1a5278;
  background: #dbeafe;
}

.bea-hub__list em[data-statut='actif'] {
  color: #166534;
  background: #dcfce7;
}

.bea-hub__list em[data-statut='maintenance'],
.bea-hub__list em[data-statut='mise_a_jour'],
.bea-hub__list em[data-statut='suspendu'],
