.bea-espace {
  --espace-accent: #1a5278;
  --espace-ink: #21618c;
  --espace-wash: #e7f1f8;
  --bea-i: 0;
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 0;
  min-height: 10.6rem;
  padding: 1.15rem 1.15rem 0.9rem;
  background: #fff;
  border: 1px solid #e8eef4;
  border-radius: 1rem;
  box-shadow: 0 8px 20px rgb(15 23 42 / 0.04);
  text-decoration: none;
  color: inherit;
  animation: bea-espace-in 0.55s cubic-bezier(0.22, 1, 0.36, 1) both;
  animation-delay: calc(var(--bea-i) * 70ms);
}

.bea-espace[data-espace='comptabilite'] {
  --espace-accent: #2f6fed;
  --espace-ink: #1d4ed8;
  --espace-wash: #e8f1ff;
}

.bea-espace[data-espace='moyens-generaux'] {
  --espace-accent: #14b8a6;
  --espace-ink: #0f766e;
  --espace-wash: #e5f7f3;
}

.bea-espace[data-espace='archives'] {
  --espace-accent: #8b7cf6;
  --espace-ink: #6d5bd0;
  --espace-wash: #f1edff;
}

.bea-espace[data-espace='credit'] {
  --espace-accent: #f59e0b;
  --espace-ink: #b45309;
  --espace-wash: #fff4e5;
}

.bea-espace[data-espace='rh'] {
  --espace-accent: #ec4899;
  --espace-ink: #be185d;
  --espace-wash: #fde8f1;
}

.bea-espace[data-espace='informatique'] {
  --espace-accent: #0ea5e9;
  --espace-ink: #0369a1;
  --espace-wash: #e7f6fd;
}

.bea-espace[data-espace='employe'] {
  --espace-accent: #0ea5e9;
  --espace-ink: #0369a1;
  --espace-wash: #e0f2fe;
}

.bea-espace[data-espace='achats'] {
  --espace-accent: #65a30d;
  --espace-ink: #3f6212;
  --espace-wash: #f0f7e6;
}

.bea-espace--actif {
  transition:
    translate 0.32s cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 0.32s ease,
    border-color 0.32s ease,
    scale 0.18s ease;
}

.bea-espace--actif::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(
    115deg,
    transparent 0%,
    rgb(255 255 255 / 0) 42%,
    rgb(255 255 255 / 0.45) 50%,
    rgb(255 255 255 / 0) 58%,
    transparent 100%
  );
  transform: translateX(-130%);
}

.bea-espace--actif:focus-visible {
  outline: 2px solid #1a5278;
  outline-offset: 2px;
}

.bea-espace--actif:hover {
  translate: 0 -6px;
  border-color: color-mix(in srgb, var(--espace-accent) 42%, #e8eef4);
  box-shadow: 0 18px 36px color-mix(in srgb, var(--espace-accent) 18%, transparent);
}

.bea-espace--actif:hover::after {
  transition: transform 0.7s ease;
  transform: translateX(130%);
}

.bea-espace--actif:active {
  translate: 0 -2px;
  scale: 0.985;
}

.bea-espace--actif:hover .bea-espace__icon {
  transform: translateY(-2px) scale(1.06);
  background: color-mix(in srgb, var(--espace-wash) 70%, #fff);
}

.bea-espace--actif:hover .bea-espace__go {
  transform: translateX(5px);
  color: var(--espace-ink);
}

.bea-espace--actif:hover .bea-badge--actif::before {
  animation: bea-espace-dot 1.35s ease-out infinite;
}

.bea-espace--bientot {
  cursor: default;
}

.bea-espace__icon {
  display: grid;
  place-items: center;
  width: 2.85rem;
  height: 2.85rem;
  margin-bottom: 0.95rem;
  flex-shrink: 0;
  border-radius: 0.75rem;
  color: var(--espace-ink);
  background: var(--espace-wash);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--espace-accent) 12%, transparent);
  transition: transform 0.32s cubic-bezier(0.22, 1, 0.36, 1), background 0.32s ease;
  animation: bea-espace-icon 0.5s cubic-bezier(0.22, 1, 0.36, 1) backwards;
  animation-delay: calc(var(--bea-i) * 70ms + 90ms);
}

.bea-espace__icon svg {
  width: 1.35rem;
  height: 1.35rem;
}

.bea-espace__title {
  margin: 0;
  font-size: 1.05rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: #0f172a;
}

.bea-espace__text,
.bea-espace__meta {
  display: none;
}

.bea-espace__mods {
  margin: 0.28rem 0 0;
  font-size: 0.8rem;
  line-height: 1.35;
  color: #64748b;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 100%;
}

.bea-espace__foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  margin-top: auto;
  padding-top: 0.95rem;
}

.bea-espace .bea-badge {
  margin-top: 0;
  padding: 0;
  border-radius: 0;
  background: transparent;
  text-transform: none;
  letter-spacing: 0;
  font-size: 0.8125rem;
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
}

.bea-espace .bea-badge::before {
  content: "";
  width: 0.42rem;
  height: 0.42rem;
  border-radius: 50%;
  background: currentColor;
  flex-shrink: 0;
}

.bea-espace .bea-badge--actif {
  color: #15803d;
  background: transparent;
}

.bea-espace .bea-badge--actif::before {
  background: #22c55e;
  box-shadow: 0 0 0 3px rgb(34 197 94 / 0.16);
}

.bea-espace .bea-badge--bientot {
  color: #64748b;
  background: transparent;
}

.bea-espace__go {
  position: static;
  flex-shrink: 0;
  display: grid;
  place-items: center;
  width: 1.35rem;
  height: 1.35rem;
  border-radius: 0;
  color: #94a3b8;
  background: transparent;
  box-shadow: none;
  transition: transform 0.32s cubic-bezier(0.22, 1, 0.36, 1), color 0.32s ease;
}

.bea-espace--bientot .bea-espace__go {
  color: #cbd5e1;
  background: transparent;
  box-shadow: none;
}

.bea-espace__go svg {
  width: 1.05rem;
  height: 1.05rem;
}

@keyframes bea-espace-in {
  from {
    opacity: 0;
    transform: translateY(14px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes bea-espace-icon {
  from {
    opacity: 0;
    transform: scale(0.82);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes bea-espace-dot {
  0% {
    box-shadow: 0 0 0 0 rgb(34 197 94 / 0.45);
  }
  70% {
    box-shadow: 0 0 0 6px rgb(34 197 94 / 0);
  }
  100% {
    box-shadow: 0 0 0 0 rgb(34 197 94 / 0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .bea-espace,
  .bea-espace--actif,
  .bea-espace--actif::after,
  .bea-espace__icon,
  .bea-espace__go,
  .bea-espace .bea-badge--actif::before {
    animation: none;
    transition: none;
  }

  .bea-espace--actif:hover,
  .bea-espace--actif:active {
    translate: none;
    scale: none;
  }
}

@media (max-width: 720px) {
  .bea-chrome__sub,
  .bea-chrome__user {
    display: none;
