  font-size: 0.84rem;
}

.bea-admin-donut__legend strong {
  margin-left: auto;
  font-size: 0.78rem;
  color: var(--bea-brand-900);
}

.bea-admin-donut__swatch {
  width: 0.65rem;
  height: 0.65rem;
  border-radius: 0.2rem;
  flex-shrink: 0;
}

.bea-admin-hbar {
  list-style: none;
  margin: 0.25rem 0 0;
  padding: 0;
  display: grid;
  gap: 0.85rem;
}

.bea-admin-hbar__meta {
  display: flex;
  justify-content: space-between;
  gap: 0.75rem;
  margin-bottom: 0.3rem;
  font-size: 0.84rem;
}

.bea-admin-hbar__meta strong {
  color: var(--bea-brand-900);
}

.bea-admin-hbar__track {
  height: 0.55rem;
  border-radius: 999px;
  background: rgb(40 116 166 / 0.1);
  overflow: hidden;
}

.bea-admin-hbar__fill {
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #2874a6, #1a5278);
  transition: width 0.45s ease;
}

.bea-admin-hbar__fill[data-key='bientot'] {
  background: linear-gradient(90deg, #5dade2, #2874a6);
}

.bea-admin-hbar__fill[data-key='inactif'] {
  background: linear-gradient(90deg, #94a3b8, #64748b);
}

.bea-admin-shortcuts {
  margin-bottom: 1.15rem;
}

.bea-admin-shortcuts > h2 {
  margin: 0 0 0.65rem;
  font-size: 1rem;
}

.bea-admin-shortcuts__grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.75rem;
}

.bea-admin-shortcut {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  padding: 0.8rem 0.85rem;
  border: 1px solid var(--bea-line);
  border-radius: 0.75rem;
  background: #fff;
  color: inherit;
  text-decoration: none;
  transition: transform 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease;
  animation: bea-admin-rise 0.45s ease both;
}

.bea-admin-shortcut:hover {
  transform: translateY(-2px);
  border-color: var(--bea-brand-400);
  box-shadow: 0 10px 24px rgb(26 82 120 / 0.1);
}

.bea-admin-shortcut__icon {
  display: grid;
  place-items: center;
  width: 2.15rem;
  height: 2.15rem;
  flex-shrink: 0;
  border-radius: 0.65rem;
  background: rgb(40 116 166 / 0.12);
  color: var(--bea-brand-700);
}

.bea-admin-shortcut__icon bea-admin-icon {
  font-size: 1.15rem;
  width: 1.15rem;
  height: 1.15rem;
  line-height: 1;
}

.bea-admin-shortcut__copy {
  display: grid;
  gap: 0.1rem;
  min-width: 0;
}

.bea-admin-shortcut__copy strong {
  font-size: 0.88rem;
  color: var(--bea-brand-900);
}

.bea-admin-shortcut__copy span {
  font-size: 0.75rem;
  color: var(--bea-ink-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.bea-admin-shortcut__chevron {
  margin-left: auto;
  color: var(--bea-ink-muted);
  font-size: 1.1rem !important;
}

.bea-admin-health__note {
  margin: 0.75rem 0 0;
  font-size: 0.78rem;
  color: var(--bea-ink-muted);
  line-height: 1.4;
}

.bea-admin-panels--equal {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.bea-admin-panel {
  background: #fff;
  border: 1px solid var(--bea-line);
  border-radius: 0.75rem;
  padding: 1rem 1.1rem;
  animation: bea-admin-rise 0.45s ease both;
}

.bea-admin-panel--list {
  display: flex;
  flex-direction: column;
  min-height: 0;
}

.bea-admin-panel__scroll {
  overflow: auto;
  max-height: min(22rem, calc(100vh - 26rem));
}

.bea-admin-panel h2 {
  margin: 0 0 0.75rem;
  font-size: 1rem;
  flex: 0 0 auto;
}

.bea-admin-table__clip {
  max-width: 14rem;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.bea-admin-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.84rem;
}

.bea-admin-table th,
.bea-admin-table td {
  text-align: left;
  padding: 0.4rem 0.35rem;
  border-bottom: 1px solid var(--bea-line);
  vertical-align: top;
}

.bea-admin-table th {
  position: sticky;
  top: 0;
  z-index: 1;
  background: #fff;
  color: var(--bea-ink-muted);
  font-weight: 700;
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.bea-admin-table tbody tr {
  transition: background 0.15s ease;
}

.bea-admin-table tbody tr:hover {
  background: #f8fafc;
}

.bea-admin-health {
  list-style: none;
  margin: 0;
  padding: 0;
}

.bea-admin-health li {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  padding: 0.4rem 0;
  border-bottom: 1px solid var(--bea-line);
  font-size: 0.9rem;
}

.bea-admin-health li strong {
  margin-left: auto;
  font-size: 0.78rem;
}

.bea-admin-health__dot {
  width: 0.65rem;
  height: 0.65rem;
  border-radius: 50%;
  background: #94a3b8;
}

.bea-admin-health__dot--ok {
  background: #16a34a;
  box-shadow: 0 0 0 0 rgb(22 163 74 / 0.45);
  animation: bea-admin-pulse 2.2s ease-out infinite;
}

@keyframes bea-admin-pulse {
  70% {
    box-shadow: 0 0 0 0.45rem rgb(22 163 74 / 0);
  }
  100% {
    box-shadow: 0 0 0 0 rgb(22 163 74 / 0);
  }
}

.bea-admin-health__dot--ko {
  background: #dc2626;
  box-shadow: 0 0 0 0 rgb(220 38 38 / 0.4);
  animation: bea-admin-pulse-ko 1.8s ease-out infinite;
}

@keyframes bea-admin-pulse-ko {
  70% {
    box-shadow: 0 0 0 0.45rem rgb(220 38 38 / 0);
  }
  100% {
    box-shadow: 0 0 0 0 rgb(220 38 38 / 0);
  }
}

