.bea-admin-matrix__table th:last-child,
.bea-admin-matrix__table td:last-child {
  position: static;
  right: auto;
  box-shadow: none;
  background: inherit;
  min-width: 0;
  width: auto;
}

.bea-admin-matrix__role-head {
  width: 6.25rem;
}

.bea-admin-matrix__role {
  font-weight: 700;
  font-size: 0.68rem;
  letter-spacing: 0.02em;
  overflow: hidden;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  line-clamp: 2;
}

.bea-admin-matrix__sticky {
  position: sticky;
  left: 0;
  z-index: 2;
  width: 17.5rem;
  background: #fff;
  text-align: left !important;
  box-shadow: 8px 0 10px -8px rgb(15 23 42 / 0.16);
}

.bea-admin-matrix__table thead .bea-admin-matrix__sticky {
  z-index: 4;
  top: 0;
  position: sticky;
  left: 0;
}

.bea-admin-matrix__module .bea-admin-matrix__sticky,
.bea-admin-matrix__module-fill {
  background: #f1f5f9;
  border-bottom-color: #e2e8f0;
  padding-top: 0.4rem;
  padding-bottom: 0.4rem;
}

.bea-admin-matrix__module .bea-admin-matrix__sticky {
  color: var(--bea-ink-muted);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.bea-admin-matrix__perm {
  font-weight: 500;
}

.bea-admin-matrix__perm code {
  display: block;
  font-size: 0.74rem;
  color: var(--bea-brand-900);
  word-break: break-all;
}

.bea-admin-matrix__perm span {
  margin-top: 0.15rem;
  color: var(--bea-ink-muted);
  font-size: 0.72rem;
  font-weight: 400;
  white-space: normal;
  overflow: hidden;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  line-clamp: 2;
}

.bea-admin-matrix__cell {
  text-align: center;
  vertical-align: middle;
  width: 6.25rem;
  padding: 0.4rem 0.2rem;
}

.bea-admin-matrix__check {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  position: relative;
  margin: 0;
  cursor: pointer;
}

.bea-admin-matrix__check input {
  width: 1.05rem;
  height: 1.05rem;
  margin: 0;
  accent-color: var(--bea-brand-800);
  cursor: pointer;
}

.bea-admin-matrix__check input:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}

.bea-admin-matrix tbody tr:hover .bea-admin-matrix__sticky {
  background: #f8fafc;
}

.bea-admin-matrix__module:hover .bea-admin-matrix__sticky,
.bea-admin-matrix__module:hover .bea-admin-matrix__module-fill {
  background: #eef2f7;
}

.bea-admin-sessions__meta {
  margin-top: 0.15rem;
  color: var(--bea-ink-muted);
  font-size: 0.75rem;
}

/* CORE ADMIN — supervision des erreurs API */
.bea-admin-errors__periods { display: flex; gap: 0.4rem; flex-wrap: wrap; align-self: center; }
.bea-admin-btn--on {
  background: var(--bea-navy, #0b2545) !important;
  border-color: var(--bea-navy, #0b2545) !important;
  color: #fff !important;
}
.bea-admin-errors__tops {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(18rem, 1fr));
  gap: 1rem;
  margin-bottom: 1rem;
}
.bea-admin-errors__tops h2 { margin: 0 0 0.6rem; font-size: 0.95rem; }
.bea-admin-errors__top { margin: 0; padding: 0; list-style: none; display: grid; gap: 0.35rem; }
.bea-admin-errors__top li {
  display: flex;
  justify-content: space-between;
  gap: 0.75rem;
  font-size: 0.82rem;
  padding: 0.35rem 0.5rem;
  border-radius: 0.45rem;
  background: #f8fafc;
}
.bea-admin-errors__top code { overflow-wrap: anywhere; }
.bea-admin-errors__status {
  display: inline-block;
  min-width: 2.6rem;
  text-align: center;
  padding: 0.15rem 0.45rem;
  border-radius: 999px;
  font-weight: 700;
  font-size: 0.78rem;
  background: #e0f2fe;
  color: #075985;
}
.bea-admin-errors__status[data-tone='danger'] { background: #fee2e2; color: #991b1b; }
.bea-admin-errors__status[data-tone='warn'] { background: #fef3c7; color: #92400e; }
.bea-admin-errors__links { display: flex; gap: 0.6rem; margin-top: 0.2rem; font-size: 0.75rem; }
.bea-admin-errors__links button { background: none; border: 0; padding: 0; cursor: pointer; font: inherit; }

.bea-admin-sessions__current td {
  background: #f0f7ff;
}

.bea-admin-sessions__current:hover td {
  background: #e8f1fc;
}

.bea-admin-sessions__current td.bea-admin-table__actions {
  background: #f0f7ff;
}

.bea-admin-ops__scroll {
  max-height: min(28rem, calc(100vh - 22rem));
}

/* Sauvegardes */
.bea-admin-backups__kicker {
  margin: 0 0 0.2rem;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--bea-ink-muted);
}

.bea-admin-backups__card h2,
.bea-admin-backups__history h2 {
  margin: 0 0 0.95rem;
}

.bea-admin-backups__stats {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.65rem;
}

.bea-admin-backups__stat {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  padding: 0.75rem 0.85rem;
  border-radius: 0.7rem;
  border: 1px solid var(--bea-line);
  background: linear-gradient(180deg, #f8fbff 0%, #fff 70%);
  animation: bea-admin-rise 0.4s ease both;
}

.bea-admin-backups__stat span {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--bea-ink-muted);
}

.bea-admin-backups__stat strong {
  font-size: 0.92rem;
  font-weight: 700;
  color: #0f172a;
  line-height: 1.3;
}

.bea-admin-backups__create .bea-admin-backups__form {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
}

.bea-admin-backups__submit {
  margin-top: 0.55rem;
  min-height: 2.55rem;
  align-self: flex-start;
  padding-inline: 1.15rem;
  box-shadow: 0 8px 18px rgb(26 82 120 / 0.18);
  transition: transform 0.18s ease, box-shadow 0.18s ease, background 0.18s ease;
}

.bea-admin-backups__submit:hover:not(:disabled) {
  transform: translateY(-1px);
  box-shadow: 0 12px 22px rgb(26 82 120 / 0.24);
}

.bea-admin-backups__history {
  margin-top: 1rem;
}

.bea-admin-backups__history-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.75rem;
  margin-bottom: 0.35rem;
}

.bea-admin-backups__history-head h2 {
  margin-bottom: 0.55rem;
}

.bea-admin-backups__level {
  display: inline-flex;
  padding: 0.18rem 0.5rem;
  border-radius: 999px;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  color: var(--bea-brand-900);
  background: #dbeafe;
}

.bea-admin-backups__status {
  display: inline-flex;
  align-items: center;
  padding: 0.18rem 0.5rem;
  border-radius: 999px;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  font-style: normal;
  color: #475569;
  background: #f1f5f9;
}

.bea-admin-backups__status[data-status='success'] {
  color: #166534;
  background: #dcfce7;
}

.bea-admin-backups__status[data-status='failed'],
.bea-admin-backups__status[data-status='error'] {
  color: #991b1b;
  background: #fee2e2;
}

.bea-admin-backups__status[data-status='running'],
.bea-admin-backups__status[data-status='pending'] {
  color: var(--bea-brand-900);
  background: #dbeafe;
}

@media (prefers-reduced-motion: reduce) {
  .bea-admin-backups__stat,
  .bea-admin-backups__submit {
    animation: none !important;
    transition: none !important;
  }

  .bea-admin-backups__submit:hover:not(:disabled) {
    transform: none;
  }
}

@media (max-width: 720px) {
  .bea-admin-backups__stats {
    grid-template-columns: 1fr;
  }
}

/* Recovery */
.bea-admin-recovery__note {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.45rem 0.85rem;
  margin: 0 0 1rem;
  padding: 0.85rem 1rem;
  border-radius: 0.75rem;
  border: 1px solid #bfdbfe;
  background: linear-gradient(135deg, #eff6ff 0%, #fff 60%);
  color: #1e3a8a;
  font-size: 0.88rem;
  line-height: 1.45;
  animation: bea-admin-rise 0.4s ease both;
}

.bea-admin-recovery__note strong {
  font-size: 0.72rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--bea-brand-900);
}

.bea-admin-recovery__kicker {
  margin: 0 0 0.2rem;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--bea-ink-muted);
}

.bea-admin-recovery__card {
  margin-bottom: 1rem;
}

.bea-admin-recovery__card-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.75rem;
  margin-bottom: 0.75rem;
}

.bea-admin-recovery__card-head h2 {
  margin: 0;
}

.bea-admin-recovery__count {
  display: inline-flex;
  align-items: center;
  padding: 0.25rem 0.6rem;
  border-radius: 999px;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  color: var(--bea-brand-900);
  background: #dbeafe;
}

.bea-admin-recovery__table td,
.bea-admin-recovery__table th {
  vertical-align: middle;
}

.bea-admin-recovery__table tbody tr {
  transition: background 0.15s ease;
}

.bea-admin-recovery__actions {
  text-align: right;
  white-space: nowrap;
  padding-top: 0.55rem !important;
  padding-bottom: 0.55rem !important;
}

.bea-admin-recovery__restore {
  min-height: 2.2rem;
  padding-inline: 0.95rem;
  box-shadow: 0 6px 14px rgb(26 82 120 / 0.16);
  transition: transform 0.18s ease, box-shadow 0.18s ease;
}

.bea-admin-recovery__restore:hover:not(:disabled) {
  transform: translateY(-1px);
  box-shadow: 0 10px 18px rgb(26 82 120 / 0.22);
}

.bea-admin-recovery__hint {
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--bea-ink-muted);
}

.bea-admin-recovery__mono {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 0.78rem;
  color: #475569;
}

@media (prefers-reduced-motion: reduce) {
  .bea-admin-recovery__note,
  .bea-admin-recovery__restore {
    animation: none !important;
    transition: none !important;
  }

  .bea-admin-recovery__restore:hover:not(:disabled) {
    transform: none;
  }
}

/* Maintenance */
.bea-admin-maint__kicker,
.bea-admin-mstates__kicker,
.bea-admin-versions__kicker {
  margin: 0 0 0.2rem;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--bea-ink-muted);
}

.bea-admin-maint__card h2,
.bea-admin-mstates__card h2,
.bea-admin-versions__card h2 {
  margin: 0 0 0.95rem;
}

.bea-admin-maint__health {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
}

.bea-admin-maint__health li {
  --delay: 0ms;
  display: flex;
  align-items: center;
  gap: 0.65rem;
  padding: 0.65rem 0.75rem;
  border-radius: 0.65rem;
  border: 1px solid var(--bea-line);
  background: #f8fafc;
  animation: bea-admin-rise 0.4s ease both;
  animation-delay: var(--delay);
}

.bea-admin-maint__health-label {
  font-size: 0.9rem;
  font-weight: 600;
  color: #0f172a;
}

.bea-admin-maint__badge {
  margin-left: auto;
  display: inline-flex;
  padding: 0.18rem 0.5rem;
  border-radius: 999px;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  color: #475569;
  background: #f1f5f9;
}

.bea-admin-maint__badge--ok {
  color: #166534;
  background: #dcfce7;
}

.bea-admin-maint__badge--ko {
  color: #991b1b;
  background: #fee2e2;
}

.bea-admin-maint__stats {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.55rem;
}

.bea-admin-maint__stat {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  padding: 0.7rem 0.8rem;
  border-radius: 0.65rem;
  border: 1px solid var(--bea-line);
  background: linear-gradient(180deg, #f8fbff 0%, #fff 70%);
}

.bea-admin-maint__stat span {
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--bea-ink-muted);
}

.bea-admin-maint__stat strong {
  font-size: 0.9rem;
  color: #0f172a;
}

.bea-admin-maint__global {
  margin-top: 1rem;
}

.bea-admin-maint__form,
.bea-admin-mstates__form,
.bea-admin-versions__form {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
}

.bea-admin-maint__check,
.bea-admin-mstates__check,
.bea-admin-versions__check {
  display: flex;
  align-items: flex-start;
  gap: 0.55rem;
  margin: 0;
  padding: 0.7rem 0.8rem;
  border-radius: 0.65rem;
  border: 1px solid var(--bea-line);
  background: #f8fafc;
  font-size: 0.88rem;
  color: #334155;
  cursor: pointer;
}

.bea-admin-maint__check input,
.bea-admin-mstates__check input,
.bea-admin-versions__check input {
  margin-top: 0.15rem;
  accent-color: var(--bea-brand-800);
}

.bea-admin-maint__submit,
.bea-admin-mstates__submit,
.bea-admin-versions__submit {
  margin-top: 0.55rem;
  align-self: flex-start;
  min-height: 2.5rem;
  padding-inline: 1.15rem;
  box-shadow: 0 8px 18px rgb(26 82 120 / 0.18);
  transition: transform 0.18s ease, box-shadow 0.18s ease;
}

.bea-admin-maint__submit:hover:not(:disabled),
.bea-admin-mstates__submit:hover:not(:disabled),
.bea-admin-versions__submit:hover:not(:disabled) {
  transform: translateY(-1px);
  box-shadow: 0 12px 22px rgb(26 82 120 / 0.24);
}

