}

.bea-admin-sec__policy-label {
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: #64748b;
}

.bea-admin-sec__policy-value {
  font-size: 0.98rem;
  font-weight: 700;
  color: #0f172a;
  line-height: 1.25;
}

.bea-admin-sec__policy-hint {
  font-size: 0.75rem;
  color: #94a3b8;
}

