}
.bea-mg__table th {
  text-align: left;
  padding: 0.7rem 1rem;
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: #64748b;
  background: #f8fafc;
  border-bottom: 1px solid #e2e8f0;
  white-space: nowrap;
}
.bea-mg__table td {
  padding: 0.75rem 1rem;
  border-bottom: 1px solid #cbd5e1;
  color: #0f172a;
  vertical-align: middle;
}
.bea-mg__table input,
.bea-mg__table select,
.bea-mg__table textarea,
.bea-ach__table input,
.bea-ach__table select,
.bea-ach__table textarea {
  font: inherit;
  font-weight: 500;
  font-size: 0.9rem;
  width: 100%;
  min-width: 0;
  box-sizing: border-box;
  padding: 0.48rem 0.7rem;
  border: 1.5px solid #475569;
  border-radius: 0.4rem;
  background: #fff;
  color: #0f172a;
}
.bea-mg__table input[type='number'],
.bea-ach__table input[type='number'] {
  width: 8.5rem;
  max-width: 100%;
  text-align: right;
}
.bea-mg__table input:focus,
.bea-mg__table select:focus,
.bea-mg__table textarea:focus,
.bea-ach__table input:focus,
.bea-ach__table select:focus,
.bea-ach__table textarea:focus {
  outline: none;
  border-color: #1a5278;
  box-shadow: 0 0 0 3px rgba(26, 82, 120, 0.16);
}
.bea-mg__lignes {
  margin-top: 1rem;
  border: 1.5px solid #475569;
  border-radius: 0.7rem;
  overflow: hidden;
  background: #fff;
}
.bea-mg__lignes .bea-mg__table-scroll {
  margin-top: 0;
  border-top: 0;
  max-height: none;
}
.bea-mg__table tbody tr {
  transition: background 0.15s ease;
  animation: beaMgRise 0.4s ease both;
}
.bea-mg__table tbody tr:hover {
  background: #f8fafc;
}
.bea-mg__code {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 0.82rem;
  background: #eef2f7;
  padding: 0.15rem 0.4rem;
  border-radius: 0.3rem;
  color: #1a5278;
}
.bea-mg__th-actions,
.bea-mg__actions-cell {
  text-align: right;
  white-space: nowrap;
}
.bea-mg__icon-btn {
  display: inline-grid;
  place-items: center;
  width: 2rem;
  height: 2rem;
  margin-left: 0.15rem;
  border: 1px solid #e2e8f0;
  border-radius: 0.45rem;
  background: #fff;
  color: #475569;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease, transform 0.15s ease;
}
.bea-mg__icon-btn mat-icon {
  font-size: 1.05rem;
  width: 1.05rem;
  height: 1.05rem;
}
.bea-mg__icon-btn:hover {
  color: #1a5278;
  border-color: #94a3b8;
  transform: translateY(-1px);
}
.bea-mg__icon-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  transform: none;
}
.bea-mg__icon-btn--danger:hover {
  color: #b91c1c;
  border-color: #fca5a5;
  background: #fef2f2;
}
.bea-mg__icon-btn--warn:hover {
  color: #b45309;
  border-color: #fcd34d;
  background: #fffbeb;
}

.bea-mg__backdrop {
  position: fixed;
  inset: 0;
  background: rgba(15, 23, 42, 0.45);
  -webkit-backdrop-filter: blur(2px);
  backdrop-filter: blur(2px);
  z-index: 40;
  animation: beaMgFade 0.2s ease both;
}
.bea-mg__modal {
  position: fixed;
  z-index: 41;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: min(36rem, calc(100vw - 1.5rem));
  max-height: calc(100vh - 2rem);
  overflow: auto;
  background: #fff;
  border-radius: 1rem;
  box-shadow: 0 24px 48px rgba(15, 23, 42, 0.28);
  animation: beaMgModal 0.28s cubic-bezier(0.22, 1, 0.36, 1) both;
}
.bea-mg__modal--sm {
  width: min(26rem, calc(100vw - 1.5rem));
}
.bea-mg__modal--lg {
  width: min(48rem, calc(100vw - 1.5rem));
}
.bea-mg__modal-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 1rem;
  padding: 1.1rem 1.25rem 0.85rem;
  border-bottom: 1px solid #eef2f7;
}
.bea-mg__modal-head h2 {
  margin: 0.1rem 0 0;
  font-size: 1.15rem;
  color: #0f172a;
}
.bea-mg__modal-body {
  padding: 1rem 1.25rem;
}
.bea-mg__modal-foot {
  display: flex;
  justify-content: flex-end;
  gap: 0.5rem;
  padding: 0 1.25rem 1.15rem;
}
.bea-mg__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.75rem;
}
.bea-mg__grid--1 {
  grid-template-columns: 1fr;
}
.bea-mg__span2 {
  grid-column: 1 / -1;
}
.bea-mg__grid label {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  font-size: 0.78rem;
  color: #475569;
  font-weight: 600;
}
.bea-mg__grid input,
.bea-mg__grid select,
.bea-mg__grid textarea {
  font: inherit;
  font-weight: 500;
  font-size: 0.9rem;
  padding: 0.55rem 0.7rem;
  border: 1.5px solid #475569;
  border-radius: 0.45rem;
  background: #fff;
  color: #0f172a;
}
.bea-mg__grid input:focus,
.bea-mg__grid select:focus,
.bea-mg__grid textarea:focus {
  outline: none;
  border-color: #1a5278;
  box-shadow: 0 0 0 3px rgba(26, 82, 120, 0.12);
}
.bea-mg__empty {
  text-align: center;
  padding: 2.25rem 1rem;
  color: #64748b;
}
.bea-mg__empty mat-icon {
  font-size: 2rem;
  width: 2rem;
  height: 2rem;
  opacity: 0.4;
}
.bea-mg__cards {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
}
@media (max-width: 900px) {
  .bea-mg__cards {
    grid-template-columns: 1fr;
  }
  .bea-mg__grid {
    grid-template-columns: 1fr;
  }
  .bea-mg__span2 {
    grid-column: auto;
  }
}
@keyframes beaMgIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@keyframes beaMgRise {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
@keyframes beaMgFade {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@keyframes beaMgModal {
  from {
    opacity: 0;
    transform: translate(-50%, -46%) scale(0.96);
  }
  to {
    opacity: 1;
    transform: translate(-50%, -50%) scale(1);
  }
}
@media (prefers-reduced-motion: reduce) {
  .bea-mg,
  .bea-mg__table tbody tr,
  .bea-mg__backdrop,
  .bea-mg__modal,
  .bea-dmg-kpi,
  .bea-dmg-kpi__icon,
  .bea-dmg-bar,
  .bea-dmg-bar__track i,
  .bea-dmg-panel {
    animation: none !important;
  }
}

/* ——— Notes de frais — design & animations ——— */
.bea-nf__registre-scroll {
  max-height: min(40rem, calc(100vh - 19rem));
  overflow: auto;
}
.bea-nf .bea-mg__head h1 {
  background: linear-gradient(120deg, #0f172a 0%, #1a5278 55%, #2874a6 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.bea-nf-kpi {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0.85rem;
  margin-bottom: 1rem;
}
.bea-nf-kpi__card {
  position: relative;
  overflow: hidden;
  padding: 1.1rem 1.15rem;
  background: #fff;
  border: 1px solid #dbe3ee;
  border-radius: 1rem;
  box-shadow: 0 8px 22px rgba(15, 23, 42, 0.05);
  animation: beaMgRise 0.45s ease both;
  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
}
.bea-nf-kpi__card:nth-child(1) { animation-delay: 0.05s; }
.bea-nf-kpi__card:nth-child(2) { animation-delay: 0.1s; }
.bea-nf-kpi__card:nth-child(3) { animation-delay: 0.15s; }
.bea-nf-kpi__card:nth-child(4) { animation-delay: 0.2s; }
.bea-nf-kpi__card::before {
  content: '';
  position: absolute;
  inset: 0 auto 0 0;
  width: 4px;
  background: linear-gradient(180deg, #1a5278, #3498db);
}
.bea-nf-kpi__card:hover {
  transform: translateY(-3px);
  border-color: #94a3b8;
  box-shadow: 0 14px 28px rgba(26, 82, 120, 0.12);
}
.bea-nf-kpi__card p {
  margin: 0;
  font-size: 0.7rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #64748b;
  font-weight: 700;
}
.bea-nf-kpi__card strong {
  display: block;
  margin-top: 0.35rem;
  font-size: clamp(1.25rem, 2vw, 1.7rem);
  letter-spacing: -0.03em;
  color: #0f172a;
}
.bea-nf-split {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(8.5rem, 1fr));
  gap: 0.65rem;
}
.bea-nf-split__item {
  padding: 0.85rem 0.75rem;
  border-radius: 0.75rem;
  background: linear-gradient(180deg, #f8fafc, #fff);
  border: 1px solid #e2e8f0;
  text-align: center;
  animation: beaMgRise 0.4s ease both;
  transition: border-color 0.15s ease, transform 0.15s ease;
}
.bea-nf-split__item:hover {
  border-color: #1a5278;
  transform: translateY(-2px);
}
.bea-nf-split__item strong {
  display: block;
  font-size: 1.35rem;
  color: #1a5278;
}
.bea-nf-split__item span {
  font-size: 0.72rem;
  color: #64748b;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
