}

/* Registre & rapports */
.bea-nf-search__spacer { flex: 1 1 0; }
.bea-nf-table th.is-num,
.bea-nf-table td.is-num,
.bea-nf-view td.is-num,
.bea-nf-view th.is-num {
  text-align: right;
  font-variant-numeric: tabular-nums;
}
.bea-nf-table .is-nowrap,
.bea-nf-view .is-nowrap { white-space: nowrap; }
.bea-nf-table td { padding-top: 0.65rem; padding-bottom: 0.65rem; border-bottom-color: #e2e8f0; }
.bea-nf-table tbody tr:last-child td { border-bottom: 0; }
.bea-nf-table tfoot td {
  padding: 0.7rem 1rem;
  font-weight: 700;
  color: #0f172a;
  background: #f0f7fc;
  border-top: 1.5px solid #cbd5e1;
