}
.bea-nf-row:hover td { background: #f5f9fd; }
.bea-nf-row td:first-child { box-shadow: inset 3px 0 0 transparent; transition: box-shadow 0.15s ease; }
.bea-nf-row:hover td:first-child { box-shadow: inset 3px 0 0 #2874a6; }
.bea-nf-cell__main { display: block; font-weight: 600; color: #0f172a; }
.bea-nf-cell__sub {
  display: block;
  margin-top: 0.1rem;
