}
.bea-nf-cell--due { color: #c2410c; font-weight: 600; }

.bea-nf-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.2rem 0.6rem;
  border-radius: 999px;
  font-size: 0.72rem;
