}
.bea-nf-badge[data-tone='draft'] { background: #e8f1f8; color: #1a5278; }
.bea-nf-badge[data-tone='progress'] { background: #eef2ff; color: #4338ca; }
.bea-nf-badge[data-tone='warn'] { background: #fff7ed; color: #c2410c; }
.bea-nf-badge[data-tone='ok'] { background: #e8f6ef; color: #0f766e; }
.bea-nf-badge[data-tone='danger'] { background: #fef2f2; color: #b91c1c; }
.bea-nf-badge[data-tone='muted'] { background: #f1f5f9; color: #475569; }

/* Aperçu (modale) */
.bea-nf-view { width: min(56rem, calc(100vw - 1.5rem)); }
.bea-nf-view__kpi--due strong { color: #c2410c; }
.bea-nf-view__progress {
