.bea-nf-view__table {
  border: 1px solid #e2e8f0;
  border-radius: 0.7rem;
  overflow: auto;
}
.bea-nf-view__table .bea-mg__table td { padding: 0.55rem 0.8rem; border-bottom-color: #eef2f7; }
.bea-nf-view__table .bea-mg__table th { padding: 0.55rem 0.8rem; }
.bea-nf-view__table tfoot td {
  padding: 0.6rem 0.8rem;
  font-weight: 700;
  background: #f0f7fc;
  color: #1a5278;
}
.bea-nf-view__timeline {
  list-style: none;
  margin: 0;
  padding: 0 0 0 0.35rem;
}
.bea-nf-view__timeline li {
  position: relative;
  display: flex;
  gap: 0.75rem;
  padding: 0 0 0.85rem;
}
.bea-nf-view__timeline li:not(:last-child)::before {
  content: '';
  position: absolute;
  left: 0.3rem;
  top: 0.85rem;
  bottom: 0;
  width: 2px;
  background: #e2e8f0;
}
.bea-nf-view__dot {
  flex-shrink: 0;
  width: 0.65rem;
  height: 0.65rem;
  margin-top: 0.3rem;
  border-radius: 50%;
  background: #94a3b8;
  box-shadow: 0 0 0 3px #fff, 0 0 0 4px #e2e8f0;
}
.bea-nf-view__dot[data-tone='draft'] { background: #1a5278; }
.bea-nf-view__dot[data-tone='progress'] { background: #4338ca; }
.bea-nf-view__dot[data-tone='warn'] { background: #ea580c; }
.bea-nf-view__dot[data-tone='ok'] { background: #0f766e; }
.bea-nf-view__dot[data-tone='danger'] { background: #dc2626; }
.bea-nf-view__timeline strong { display: block; font-size: 0.88rem; color: #0f172a; }
.bea-nf-view__timeline small { font-size: 0.76rem; color: #64748b; }
.bea-nf-view__timeline p { margin: 0.25rem 0 0; font-size: 0.84rem; color: #334155; font-style: italic; }
.bea-nf-view__foot-left { margin-right: auto; }

@media (max-width: 900px) {
  .bea-nf-view .bea-ct-view__kpis { grid-template-columns: 1fr; }
  .bea-nf-search__spacer { display: none; }
}
@media (prefers-reduced-motion: reduce) {
  .bea-nf-kpi__card,
  .bea-nf-split__item,
  .bea-nf-fiche,
  .bea-nf-row,
  .bea-nfd-kpi__card,
  .bea-nfd-panel,
  .bea-nfd-flow li,
  .bea-nfd-chart__bar {
