  }
}

/* Paiements notes de frais */
.bea-pay-filters .bea-mg__field { min-width: 9rem; }
.bea-pay-table th.is-sortable { cursor: pointer; user-select: none; }
.bea-pay-table th.is-sortable:hover { color: #1a5278; }
.bea-pay-sort { font-size: 0.9rem; width: 0.9rem; height: 0.9rem; vertical-align: -0.15rem; color: #1a5278; }
.bea-nf-table tr.is-cancelled td { color: #94a3b8; }
