.bea-pay-motif { max-width: 14rem; white-space: normal; margin: 0; }
.bea-pay-ref { font-size: 0.82rem; color: #334155; }
.bea-pay-user { font-weight: 500; font-size: 0.84rem; }
.bea-pay-btn mat-icon { color: #0f766e; }
.bea-mg__icon-btn.bea-pay-btn:hover { border-color: #99f6e4; background: #f0fdfa; }
.bea-pay-cta { display: flex; justify-content: flex-end; margin-top: 0.85rem; }
.bea-pay-lock { display: inline-flex; align-items: center; gap: 0.3rem; font-size: 0.8rem; color: #64748b; }
.bea-pay-lock mat-icon { font-size: 1rem; width: 1rem; height: 1rem; }
.bea-pay-obs {
  margin-top: 0.6rem;
  padding: 0.55rem 0.75rem;
  border-left: 3px solid #cbd5e1;
  background: #f8fafc;
  border-radius: 0 0.4rem 0.4rem 0;
}

.bea-pay-form { width: min(50rem, calc(100vw - 1.5rem)); }
.bea-pay-steps { display: inline-flex; align-items: center; gap: 0.2rem; font-size: 0.74rem; font-weight: 700; color: #94a3b8; }
.bea-pay-steps mat-icon { font-size: 1rem; width: 1rem; height: 1rem; }
.bea-pay-steps .is-on {
  padding: 0.12rem 0.55rem;
  border-radius: 999px;
  background: #1a5278;
  color: #fff;
}
.bea-pay-search { margin-bottom: 0.85rem; }
.bea-pay-pick { list-style: none; margin: 0; padding: 0; display: grid; gap: 0.5rem; }
.bea-pay-pick li { animation: beaMgRise 0.3s ease both; }
.bea-pay-pick button {
  width: 100%;
  display: grid;
  grid-template-columns: 1fr auto auto;
  align-items: center;
  gap: 1rem;
  padding: 0.75rem 0.9rem;
