.bea-pay-pick__main { display: flex; flex-direction: column; gap: 0.2rem; min-width: 0; }
.bea-pay-pick__main code { align-self: flex-start; }
.bea-pay-pick__main strong { color: #0f172a; }
.bea-pay-pick__main small { color: #64748b; font-size: 0.78rem; }
.bea-pay-pick__amount { display: flex; flex-direction: column; align-items: flex-end; gap: 0.2rem; }
.bea-pay-pick__amount small { font-size: 0.68rem; text-transform: uppercase; letter-spacing: 0.05em; color: #64748b; }
.bea-pay-pick__amount strong { color: #c2410c; font-variant-numeric: tabular-nums; }
.bea-pay-pick__empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.3rem;
  padding: 2rem 1rem;
  color: #64748b;
