}
.bea-pay-pick__empty mat-icon { font-size: 2rem; width: 2rem; height: 2rem; color: #0f766e; opacity: 0.6; }
.bea-pay-pick__empty p { margin: 0; font-weight: 600; }

.bea-pay-registre {
  margin-bottom: 1rem;
  padding: 0.9rem 1rem 1rem;
  border: 1px solid #dbe7f3;
  border-radius: 0.9rem;
  background: linear-gradient(180deg, #f5f9fd, #fff);
}
.bea-pay-registre__head { display: flex; align-items: center; justify-content: space-between; gap: 0.5rem; margin-bottom: 0.5rem; }
.bea-pay-registre__head h3 { margin: 0; display: flex; align-items: center; gap: 0.4rem; font-size: 0.9rem; color: #1a5278; }
.bea-pay-registre__head h3 mat-icon { font-size: 1.1rem; width: 1.1rem; height: 1.1rem; }
.bea-pay-registre__wide { grid-column: 1 / -1; }
.bea-pay-change { padding: 0.3rem 0.65rem; font-size: 0.78rem; }
.bea-pay-kpis { margin: 0.85rem 0 0; }
.bea-pay-kpis > div.is-due strong { color: #c2410c; }
.bea-pay-amount { display: flex; gap: 0.35rem; }
.bea-pay-amount input { flex: 1; min-width: 0; }
.bea-pay-amount__all {
  padding: 0 0.7rem;
  border: 1.5px solid #1a5278;
  border-radius: 0.45rem;
  background: #e8f1f8;
  color: #1a5278;
  font: inherit;
  font-size: 0.78rem;
  font-weight: 700;
  cursor: pointer;
}
.bea-pay-amount__all:hover { background: #1a5278; color: #fff; }
.bea-pay-modes { display: flex; flex-wrap: wrap; gap: 0.4rem; }
.bea-pay-modes button {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.45rem 0.8rem;
