.bea-pay-modes button.is-on { border-color: #1a5278; background: #1a5278; color: #fff; }
.bea-pay-file { display: flex; flex-direction: column; gap: 0.3rem; }
.bea-pay-file input[type='file'] { border-style: dashed; background: #f8fafc; }
.bea-pay-file small { display: inline-flex; align-items: center; gap: 0.25rem; font-weight: 500; color: #64748b; }
.bea-pay-file small mat-icon { font-size: 1rem; width: 1rem; height: 1rem; }
.bea-pay-apres {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  margin-top: 0.25rem;
  padding: 0.65rem 0.85rem;
