.bea-pay-apres[data-tone='ok'] { background: #ecfdf5; color: #065f46; border-color: #a7f3d0; }
.bea-pay-apres[data-tone='danger'] { background: #fef2f2; color: #991b1b; border-color: #fecaca; }
