@media (max-width: 640px) {
  .bea-pay-pick button { grid-template-columns: 1fr; }
  .bea-pay-pick__amount { align-items: flex-start; }
}

/* Dashboard notes de frais */
.bea-nfd-kpi {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0.85rem;
  margin-bottom: 1rem;
}
.bea-nfd-kpi__card {
  --tone: #1a5278;
  --tone-bg: #e8f1f8;
  position: relative;
  overflow: hidden;
  display: flex;
  align-items: flex-start;
  gap: 0.8rem;
  padding: 1rem 1.1rem 1.15rem;
  background: #fff;
  border: 1px solid #dbe3ee;
  border-radius: 1rem;
  box-shadow: 0 8px 22px rgba(15, 23, 42, 0.05);
  animation: beaMgRise 0.45s ease both;
  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
}
.bea-nfd-kpi__card[data-tone='indigo'] { --tone: #4338ca; --tone-bg: #eef2ff; }
.bea-nfd-kpi__card[data-tone='orange'] { --tone: #c2410c; --tone-bg: #fff7ed; }
.bea-nfd-kpi__card[data-tone='green'] { --tone: #0f766e; --tone-bg: #e8f6ef; }
.bea-nfd-kpi__card:nth-child(2) { animation-delay: 0.06s; }
.bea-nfd-kpi__card:nth-child(3) { animation-delay: 0.12s; }
.bea-nfd-kpi__card:nth-child(4) { animation-delay: 0.18s; }
.bea-nfd-kpi__card::after {
  content: '';
  position: absolute;
  right: -1.5rem;
  top: -1.5rem;
  width: 5.5rem;
  height: 5.5rem;
  border-radius: 50%;
  background: var(--tone-bg);
  opacity: 0.7;
  pointer-events: none;
}
.bea-nfd-kpi__card:hover {
  transform: translateY(-3px);
  border-color: var(--tone);
  box-shadow: 0 14px 28px rgba(15, 23, 42, 0.1);
}
.bea-nfd-kpi__icon {
  position: relative;
  z-index: 1;
  display: inline-grid;
  place-items: center;
  flex-shrink: 0;
  width: 2.5rem;
  height: 2.5rem;
  border-radius: 0.75rem;
  background: var(--tone-bg);
  color: var(--tone);
}
.bea-nfd-kpi__card > div { position: relative; z-index: 1; min-width: 0; }
.bea-nfd-kpi__card p {
  margin: 0;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #64748b;
}
.bea-nfd-kpi__card strong {
  display: block;
  margin-top: 0.25rem;
  font-size: clamp(1.2rem, 1.9vw, 1.6rem);
  letter-spacing: -0.03em;
  color: #0f172a;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.bea-nfd-kpi__card strong em {
  font-style: normal;
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0;
  color: #64748b;
}
.bea-nfd-kpi__card small {
  display: block;
  margin-top: 0.2rem;
  font-size: 0.76rem;
  color: var(--tone);
}
.bea-nfd-kpi__bar {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 4px;
  background: #eef2f7;
}
.bea-nfd-kpi__bar i {
  display: block;
  height: 100%;
  background: linear-gradient(90deg, #1a5278, #0f766e);
  transition: width 0.8s cubic-bezier(0.22, 1, 0.36, 1);
}

.bea-nfd-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.5fr) minmax(0, 1fr);
  gap: 1rem;
}
.bea-nfd-panel { animation: beaMgRise 0.45s ease 0.2s both; }
.bea-nfd-more { padding: 0.35rem 0.7rem; font-size: 0.8rem; }
.bea-nfd-more mat-icon { font-size: 1rem; width: 1rem; height: 1rem; }

.bea-nfd-chart {
  display: grid;
  grid-template-columns: repeat(12, 1fr);
  gap: 0.4rem;
  align-items: end;
  height: 13rem;
  padding: 1rem 1.15rem 0.25rem;
}
.bea-nfd-chart__col {
  display: flex;
  flex-direction: column;
  align-items: center;
  height: 100%;
  gap: 0.25rem;
}
.bea-nfd-chart__val { min-height: 1rem; font-size: 0.7rem; font-weight: 700; color: #1a5278; }
.bea-nfd-chart__track {
  flex: 1;
  width: 100%;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  gap: 2px;
  border-radius: 0.4rem;
  background: linear-gradient(180deg, transparent, #f8fafc);
}
.bea-nfd-chart__bar {
  width: 42%;
  max-width: 0.9rem;
  border-radius: 0.3rem 0.3rem 0 0;
  background: linear-gradient(180deg, #2874a6, #1a5278);
  transform-origin: bottom;
  animation: beaNfdGrow 0.6s cubic-bezier(0.22, 1, 0.36, 1) both;
}
.bea-nfd-chart__bar--paid { background: linear-gradient(180deg, #14b8a6, #0f766e); }
.bea-nfd-chart__label { font-size: 0.68rem; font-weight: 600; color: #64748b; text-transform: capitalize; }
.bea-nfd-chart__col.is-current .bea-nfd-chart__label { color: #1a5278; font-weight: 800; }
.bea-nfd-chart__col.is-current .bea-nfd-chart__track { background: linear-gradient(180deg, #f0f7fc, #e8f1f8); }
.bea-nfd-legend {
  display: flex;
  gap: 1rem;
  padding: 0.5rem 1.15rem 0.9rem;
  font-size: 0.75rem;
  color: #64748b;
}
.bea-nfd-legend span { display: inline-flex; align-items: center; gap: 0.35rem; }
.bea-nfd-legend i { width: 0.7rem; height: 0.7rem; border-radius: 0.2rem; background: #1a5278; }
.bea-nfd-legend i.is-paid { background: #0f766e; }
@keyframes beaNfdGrow {
  from { transform: scaleY(0); }
  to { transform: scaleY(1); }
}

.bea-nfd-flow {
  list-style: none;
  margin: 0;
  padding: 0.85rem 1.15rem 1rem;
  display: grid;
  gap: 0.6rem;
}
.bea-nfd-flow li {
  display: grid;
  grid-template-columns: 7.5rem 1fr 2rem;
  align-items: center;
  gap: 0.65rem;
  font-size: 0.84rem;
  animation: beaMgRise 0.4s ease both;
}
.bea-nfd-flow__label { display: inline-flex; align-items: center; gap: 0.5rem; color: #334155; font-weight: 600; }
.bea-nfd-flow__label .bea-nf-view__dot { margin-top: 0; }
.bea-nfd-flow__track {
  height: 0.5rem;
  border-radius: 999px;
  background: #eef2f7;
  overflow: hidden;
}
.bea-nfd-flow__track i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: #94a3b8;
  transition: width 0.7s cubic-bezier(0.22, 1, 0.36, 1);
}
.bea-nfd-flow__track i[data-tone='draft'] { background: #1a5278; }
.bea-nfd-flow__track i[data-tone='progress'] { background: #6366f1; }
.bea-nfd-flow__track i[data-tone='warn'] { background: #f97316; }
.bea-nfd-flow__track i[data-tone='ok'] { background: #0f766e; }
.bea-nfd-flow__track i[data-tone='danger'] { background: #dc2626; }
.bea-nfd-flow strong { text-align: right; color: #0f172a; font-variant-numeric: tabular-nums; }

@media (max-width: 1100px) {
  .bea-nfd-kpi { grid-template-columns: 1fr 1fr; }
  .bea-nfd-grid { grid-template-columns: 1fr; }
}
@media (max-width: 640px) {
  .bea-nfd-kpi { grid-template-columns: 1fr; }
  .bea-nfd-chart { gap: 0.2rem; padding-inline: 0.6rem; }
}

/* ——— Contrats & échéances ——— */
.bea-ct {
  animation: beaMgFade 0.35s ease both;
}
.bea-ct .bea-nf-kpi__card:nth-child(5) { animation-delay: 0.25s; }
.bea-ct .bea-nf-kpi__card:nth-child(6) { animation-delay: 0.3s; }
.bea-ct .bea-nf-kpi__card:nth-child(7) { animation-delay: 0.35s; }
.bea-ct .bea-nf-kpi__card:nth-child(8) { animation-delay: 0.4s; }
.bea-ct .bea-nf-kpi__card:nth-child(9) { animation-delay: 0.45s; }
.bea-ct .bea-nf-kpi__card:nth-child(10) { animation-delay: 0.5s; }
.bea-ct .bea-nf-kpi__card:nth-child(11) { animation-delay: 0.55s; }
.bea-ct .bea-nf-kpi__card:nth-child(12) { animation-delay: 0.6s; }
.bea-ct a.bea-nf-kpi__card {
  display: block;
  color: inherit;
  text-decoration: none;
  cursor: pointer;
}
.bea-ct-empty {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  margin-bottom: 1rem;
  padding: 0.85rem 1rem;
  border-radius: 0.9rem;
  background: #fff;
  border: 1px dashed #cbd5e1;
  color: #64748b;
  animation: beaMgRise 0.4s ease both;
}
.bea-ct-empty mat-icon {
  color: #1a5278;
  opacity: 0.7;
}
.bea-ct-empty p { margin: 0; font-weight: 600; }
.bea-ct-empty small { font-size: 0.8rem; color: #64748b; line-height: 1.5; }
.bea-ct-empty small a { margin-left: 0.35rem; color: #1a5278; font-weight: 600; }
.bea-ct-panel {
  margin-top: 0.85rem;
  animation: beaMgRise 0.45s ease both;
}
.bea-ct-panel:nth-of-type(2) { animation-delay: 0.08s; }
.bea-ct-panel:nth-of-type(3) { animation-delay: 0.14s; }
.bea-ct .bea-mg__search {
  margin-bottom: 0.85rem;
  padding: 0.85rem;
  background: #fff;
  border: 1px solid #dbe3ee;
  border-radius: 1rem;
  box-shadow: 0 8px 22px rgba(15, 23, 42, 0.04);
  animation: beaMgRise 0.4s ease both;
}
.bea-ct .bea-mg__table-scroll {
  background: #fff;
  border: 1px solid #dbe3ee;
  border-radius: 1rem;
  box-shadow: 0 8px 22px rgba(15, 23, 42, 0.05);
  animation: beaMgRise 0.45s ease 0.08s both;
  overflow: auto;
}
.bea-ct-row {
  animation: beaMgRise 0.35s ease both;
}
.bea-ct-row:hover td {
  background: #f8fafc;
}
.bea-ct-badge {
  display: inline-flex;
  align-items: center;
  padding: 0.18rem 0.55rem;
  border-radius: 999px;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.03em;
  background: #eef2f7;
  color: #334155;
}
.bea-ct-badge[data-tone='ACTIF'],
.bea-ct-badge[data-tone='PAYE'] { background: #e8f6ef; color: #0f766e; }
.bea-ct-badge[data-tone='BROUILLON'],
.bea-ct-badge[data-tone='A_VENIR'],
.bea-ct-badge[data-tone='INFO'] { background: #e8f1f8; color: #1a5278; }
.bea-ct-badge[data-tone='EN_VALIDATION'],
.bea-ct-badge[data-tone='ATTENTION'],
.bea-ct-badge[data-tone='PARTIELLEMENT_PAYE'] { background: #fff7ed; color: #c2410c; }
.bea-ct-badge[data-tone='EN_RETARD'],
.bea-ct-badge[data-tone='URGENT'],
.bea-ct-badge[data-tone='CRITIQUE'],
.bea-ct-badge[data-tone='REJETE'] { background: #fef2f2; color: #b91c1c; }
.bea-ct-badge[data-tone='SUSPENDU'],
.bea-ct-badge[data-tone='EXPIRE'] { background: #f1f5f9; color: #475569; }
.bea-ct-link {
  color: #1a5278;
  font-weight: 700;
  text-decoration: none;
}
.bea-ct-link:hover { text-decoration: underline; }
.bea-ct-section h2 {
  margin: 0 0 0.75rem;
  font-size: 0.95rem;
  color: #0f172a;
}
.bea-ct-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(14rem, 1fr));
  gap: 0.75rem;
}
.bea-ct-grid label {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  font-size: 0.78rem;
  font-weight: 600;
  color: #475569;
}
.bea-ct-grid input,
.bea-ct-grid select {
  font: inherit;
  font-weight: 500;
  font-size: 0.9rem;
  padding: 0.55rem 0.7rem;
  border: 1.5px solid #cbd5e1;
  border-radius: 0.55rem;
  background: #fff;
  color: #0f172a;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}
.bea-ct-grid > button { align-self: end; }
.bea-ct-section .bea-ct-note { padding: 0 1rem 0.25rem; }
.bea-ct-grid input:focus,
.bea-ct-grid select:focus {
  outline: none;
  border-color: #1a5278;
  box-shadow: 0 0 0 3px rgba(26, 82, 120, 0.12);
}
.bea-ct-note {
  margin: 0.85rem 0 0;
  color: #64748b;
  font-size: 0.86rem;
}
.bea-ct-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
  margin: 1rem 0 0.75rem;
}
.bea-ct-tabs button {
  border: 1px solid #dbe3ee;
  background: #fff;
  color: #334155;
  border-radius: 999px;
  padding: 0.4rem 0.85rem;
  font: inherit;
  font-size: 0.82rem;
  font-weight: 700;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease, transform 0.15s ease;
}
.bea-ct-tabs button:hover { transform: translateY(-1px); }
.bea-ct-tabs button.is-on {
  background: #1a5278;
  border-color: #1a5278;
  color: #fff;
}
.bea-ct-pane {
  animation: beaMgRise 0.35s ease both;
}
.bea-ct-list {
  list-style: none;
  margin: 0.75rem 0 0;
  padding: 0;
  display: grid;
  gap: 0.55rem;
}
.bea-ct-list li {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem 0.85rem;
  align-items: center;
  padding: 0.75rem 0.9rem;
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 0.8rem;
  animation: beaMgRise 0.35s ease both;
}
.bea-ct-types {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  padding: 0.9rem 1rem 1.1rem;
}
.bea-ct-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.4rem 0.7rem;
  border-radius: 999px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  font-weight: 700;
  color: #0f172a;
  animation: beaMgRise 0.35s ease both;
}
.bea-ct-chip small {
  font-weight: 600;
  color: #64748b;
}

/* Liste des contrats */
.bea-ct .bea-mg__table-scroll {
  max-height: calc(100vh - 17rem);
  overflow-x: auto;
  overflow-y: auto;
}
.bea-ct .bea-mg__table {
  width: 100%;
  font-size: 0.84rem;
}
.bea-ct .bea-mg__table th {
  padding: 0.6rem 0.65rem;
  font-size: 0.68rem;
  white-space: normal;
}
.bea-ct .bea-mg__table td {
  padding: 0.6rem 0.65rem;
  border-bottom-color: #e2e8f0;
  vertical-align: middle;
  overflow-wrap: anywhere;
}
.bea-ct .bea-mg__table tbody tr:last-child td { border-bottom: 0; }
.bea-ct .bea-mg__icon-btn {
  width: 1.85rem;
  height: 1.85rem;
}
.bea-ct-table .is-nowrap { white-space: nowrap; overflow-wrap: normal; }
.bea-ct-table .is-num { text-align: right; font-variant-numeric: tabular-nums; }
.bea-ct-table .is-wide {
  min-width: 6rem;
  max-width: 14rem;
  line-height: 1.3;
  overflow-wrap: break-word;
}
.bea-ct-table .is-actions,
.bea-ct-table .bea-mg__actions-cell { text-align: center; white-space: nowrap; }
.bea-ct-sub {
  display: block;
  margin-top: 0.2rem;
  font-size: 0.75rem;
  color: #64748b;
  line-height: 1.25;
  white-space: normal;
}
.bea-ct-strong { font-weight: 650; color: #0f172a; }
.bea-ct-count {
  margin: 0.55rem 0.25rem 0;
  font-size: 0.8rem;
  color: #64748b;
}

/* Aperçu (modale) */
.bea-ct-view {
  display: flex;
  flex-direction: column;
  width: min(52rem, calc(100vw - 1.5rem));
  max-height: calc(100vh - 3rem);
  overflow: hidden;
}
.bea-ct-view__head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 1rem;
  padding: 1.15rem 1.35rem 1rem;
  background: linear-gradient(135deg, #f0f7fc 0%, #fff 70%);
  border-bottom: 1px solid #e2e8f0;
}
.bea-ct-view__kicker {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin: 0 0 0.35rem;
}
.bea-ct-view__head h2 {
  margin: 0;
  font-size: 1.25rem;
  color: #0f172a;
}
.bea-ct-view__sub {
  margin: 0.2rem 0 0;
  font-size: 0.85rem;
  color: #64748b;
}
.bea-ct-view__close {
  display: inline-grid;
  place-items: center;
  width: 2.2rem;
  height: 2.2rem;
  flex-shrink: 0;
  border: 1px solid #dbe3ee;
  border-radius: 0.6rem;
  background: #fff;
  color: #334155;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease, transform 0.15s ease;
}
.bea-ct-view__close:hover {
  background: #fef2f2;
  border-color: #fecaca;
  color: #b91c1c;
  transform: rotate(90deg);
}
.bea-ct-view__body {
  flex: 1;
  overflow: auto;
  padding: 1rem 1.35rem 0.5rem;
}
.bea-ct-view__kpis {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.65rem;
  margin-bottom: 1rem;
}
.bea-ct-view__kpis > div {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  padding: 0.75rem 0.85rem;
  border: 1px solid #e2e8f0;
  border-radius: 0.8rem;
  background: #f8fafc;
}
.bea-ct-view__kpis span {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: #64748b;
}
.bea-ct-view__kpis strong {
  font-size: 1rem;
  color: #0f172a;
  font-variant-numeric: tabular-nums;
}
.bea-ct-view__kpis small {
  font-size: 0.78rem;
  color: #1a5278;
}
.bea-ct-view__section {
  margin-bottom: 1rem;
}
.bea-ct-view__section h3 {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  margin: 0 0 0.5rem;
  font-size: 0.9rem;
  color: #1a5278;
}
.bea-ct-view__section h3 mat-icon {
  font-size: 1.1rem;
  width: 1.1rem;
  height: 1.1rem;
}
.bea-ct-view__section h3 small {
  padding: 0 0.45rem;
  border-radius: 999px;
  background: #e8f1f8;
  font-size: 0.72rem;
}
.bea-ct-view__dl {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(13rem, 1fr));
  gap: 0.5rem 1rem;
  margin: 0;
}
.bea-ct-view__dl dt {
  font-size: 0.75rem;
  font-weight: 600;
  color: #64748b;
}
.bea-ct-view__dl dd {
  margin: 0.1rem 0 0;
  font-weight: 600;
  color: #0f172a;
  overflow-wrap: anywhere;
}
.bea-ct-view__text {
  margin: 0 0 0.35rem;
  color: #334155;
  white-space: pre-line;
}
.bea-ct-view__text--muted { color: #64748b; font-style: italic; }
.bea-ct-view__rows {
  list-style: none;
  margin: 0;
  padding: 0;
  border: 1px solid #e2e8f0;
  border-radius: 0.7rem;
  overflow: hidden;
}
.bea-ct-view__rows li {
  display: grid;
  grid-template-columns: 6.5rem 1fr auto auto;
  align-items: center;
  gap: 0.75rem;
  padding: 0.5rem 0.75rem;
  font-size: 0.86rem;
}
.bea-ct-view__rows li + li { border-top: 1px solid #eef2f7; }
.bea-ct-view__rows li:nth-child(even) { background: #f8fafc; }
.bea-ct-view__rows .is-num { font-variant-numeric: tabular-nums; }
.bea-ct-view__none {
  margin: 0;
  font-size: 0.85rem;
  color: #94a3b8;
}
.bea-ct-view__foot {
  display: flex;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: 0.5rem;
  padding: 0.85rem 1.35rem;
  border-top: 1px solid #e2e8f0;
  background: #fff;
}
.bea-ct-view__loading {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  padding: 2.5rem;
  justify-content: center;
  color: #64748b;
}
.bea-ct-view__spinner {
  width: 1.1rem;
  height: 1.1rem;
  border: 2px solid #cbd5e1;
  border-top-color: #1a5278;
  border-radius: 50%;
  animation: beaCtSpin 0.8s linear infinite;
}
@keyframes beaCtSpin { to { transform: rotate(360deg); } }

/* Fiche : statut et cycle de vie */
.bea-ct-life,
.bea-ct-suivi {
  padding: 1rem 1.1rem 1.1rem;
}
.bea-ct-life h2,
.bea-ct-suivi h2 {
  margin: 0 0 0.4rem;
  font-size: 0.95rem;
  color: #0f172a;
}
.bea-ct-life__hint {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem;
  margin: 0;
  font-size: 0.86rem;
  color: #475569;
}
.bea-ct-steps {
  display: flex;
  list-style: none;
  margin: 0.9rem 0;
  padding: 0;
  counter-reset: none;
}
.bea-ct-steps li {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 0.45rem;
  position: relative;
  font-size: 0.8rem;
  font-weight: 600;
  color: #94a3b8;
}
.bea-ct-steps li:not(:last-child)::after {
  content: '';
  flex: 1;
  height: 2px;
  margin: 0 0.5rem;
  background: #e2e8f0;
  border-radius: 2px;
}
.bea-ct-steps__dot {
  display: inline-grid;
  place-items: center;
  width: 1.6rem;
  height: 1.6rem;
  flex-shrink: 0;
  border-radius: 50%;
  border: 2px solid #e2e8f0;
  background: #fff;
  font-size: 0.75rem;
}
.bea-ct-steps li.is-done { color: #0f766e; }
.bea-ct-steps li.is-done .bea-ct-steps__dot { background: #0f766e; border-color: #0f766e; color: #fff; }
.bea-ct-steps li.is-done:not(:last-child)::after { background: #0f766e; }
.bea-ct-steps li.is-on { color: #1a5278; }
.bea-ct-steps li.is-on .bea-ct-steps__dot {
  border-color: #1a5278;
  background: #1a5278;
  color: #fff;
  box-shadow: 0 0 0 4px rgba(26, 82, 120, 0.15);
}
.bea-ct-life__actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 0.6rem;
  margin: 0;
  padding: 0.85rem 0 0;
  min-width: 0;
  border: 0;
  border-top: 1px solid #eef2f7;
}
.bea-ct-life__actions:disabled { opacity: 0.6; cursor: progress; }
.bea-ct-life__group {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}
.bea-ct-danger { color: #b91c1c !important; }
.bea-ct-danger:hover { background: #fef2f2 !important; border-color: #fecaca !important; }
.bea-ct-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}
.bea-ct-field-error {
  font-size: 0.74rem;
  font-weight: 600;
  color: #b91c1c;
}
.bea-ct-grid input[aria-invalid='true'] { border-color: #f87171 !important; }

/* Fiche : suivi (onglets) */
.bea-ct-suivi__head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  padding-bottom: 0.75rem;
  border-bottom: 1px solid #eef2f7;
}
.bea-ct-suivi__head h2 { margin: 0; }
.bea-ct-suivi .bea-ct-tabs { margin: 0; }
.bea-ct-tabs button {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
}
.bea-ct-tabs button mat-icon {
  font-size: 1rem;
  width: 1rem;
  height: 1rem;
}
.bea-ct-tabs button small {
  min-width: 1.2rem;
  padding: 0 0.3rem;
  border-radius: 999px;
  background: #eef2f7;
  color: #334155;
  font-size: 0.7rem;
  text-align: center;
}
.bea-ct-tabs button.is-on small { background: rgba(255, 255, 255, 0.22); color: #fff; }
.bea-ct-help {
  display: flex;
  align-items: flex-start;
  gap: 0.45rem;
  margin: 0.85rem 0;
  padding: 0.6rem 0.75rem;
  border-radius: 0.6rem;
  background: #f0f7fc;
  color: #1e3a5f;
  font-size: 0.84rem;
  line-height: 1.4;
}
.bea-ct-help mat-icon {
  flex-shrink: 0;
  font-size: 1.05rem;
  width: 1.05rem;
  height: 1.05rem;
  color: #1a5278;
}
.bea-ct-inline {
  grid-template-columns: repeat(auto-fit, minmax(11rem, 1fr));
  align-items: end;
}
