.bea-ct-dash__amount { font-weight: 700; font-size: 0.85rem; font-variant-numeric: tabular-nums; white-space: nowrap; }
.bea-ct-dash__amount small { font-weight: 500; color: #64748b; }
.bea-ct-dash__none { padding: 0.9rem 0.5rem; color: #94a3b8; font-size: 0.86rem; }
.bea-ct-bars { list-style: none; margin: 0; padding: 0.4rem 1rem 1rem; display: flex; flex-direction: column; gap: 0.6rem; }
.bea-ct-bars li { display: grid; grid-template-columns: minmax(7rem, 11rem) 1fr auto; align-items: center; gap: 0.6rem; font-size: 0.82rem; }
.bea-ct-bars__label { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-weight: 600; color: #334155; }
.bea-ct-bars__label small { margin-left: 0.25rem; padding: 0 0.35rem; border-radius: 999px; background: #eef2f7; font-size: 0.7rem; }
.bea-ct-bars__track { height: 0.55rem; border-radius: 999px; background: #eef2f7; overflow: hidden; }
.bea-ct-bars__fill { display: block; height: 100%; border-radius: inherit; background: linear-gradient(90deg, #1a5278, #3b82c4); animation: beaCtGrow 0.7s ease both; transform-origin: left; }
.bea-ct-bars__fill--alt { background: linear-gradient(90deg, #0f766e, #34b39f); }
.bea-ct-bars__value { font-weight: 700; font-variant-numeric: tabular-nums; color: #0f172a; white-space: nowrap; }
@keyframes beaCtGrow { from { transform: scaleX(0); } to { transform: scaleX(1); } }

/* Rapports */
.bea-ct-reports {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.85rem;
  margin-bottom: 0.85rem;
}
.bea-ct-reports__group h2 { margin: 0 0 0.45rem; font-size: 0.74rem; text-transform: uppercase; letter-spacing: 0.06em; color: #64748b; }
.bea-ct-reports__item {
  display: flex;
  align-items: flex-start;
  gap: 0.6rem;
  width: 100%;
  margin-bottom: 0.4rem;
  padding: 0.6rem 0.7rem;
  border: 1px solid #e2e8f0;
  border-radius: 0.75rem;
  background: #fff;
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition: border-color 0.15s ease, transform 0.15s ease;
}
.bea-ct-reports__item:hover { transform: translateY(-1px); border-color: #b6cde0; }
.bea-ct-reports__item.is-on { border-color: #1a5278; background: #f0f7fc; box-shadow: 0 0 0 3px rgba(26, 82, 120, 0.1); }
.bea-ct-reports__item mat-icon { color: #1a5278; flex-shrink: 0; }
.bea-ct-reports__item span { display: flex; flex-direction: column; gap: 0.1rem; }
.bea-ct-reports__item strong { font-size: 0.86rem; color: #0f172a; }
.bea-ct-reports__item small { font-size: 0.74rem; color: #64748b; }

@media (max-width: 1100px) {
  .bea-ct-dash__hero { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .bea-ct-reports { grid-template-columns: 1fr; }
}
@media (max-width: 900px) {
  .bea-ct-form__grid,
  .bea-ct-dash__grid { grid-template-columns: 1fr; }
  .bea-ct-span2 { grid-column: auto; }
  .bea-ct-dash__hero { grid-template-columns: 1fr; }
}

@media (max-width: 900px) {
  .bea-ct .bea-nf-kpi { grid-template-columns: 1fr 1fr; }
  .bea-ct-view__kpis { grid-template-columns: 1fr; }
  .bea-ct-view__rows li { grid-template-columns: 1fr auto; }
  .bea-ct-steps { flex-wrap: wrap; gap: 0.5rem; }
  .bea-ct-steps li::after { display: none; }
}
@media (prefers-reduced-motion: reduce) {
  .bea-ct,
  .bea-ct-empty,
  .bea-ct-panel,
  .bea-ct-row,
  .bea-ct-pane,
  .bea-ct-list li,
  .bea-ct-chip,
  .bea-ct .bea-mg__search,
  .bea-ct .bea-mg__table-scroll {
    animation: none !important;
  }
}

