  font-size: 1.05rem;
  width: 1.05rem;
  height: 1.05rem;
}
.bea-dmg-kpis {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.85rem;
  margin-bottom: 1rem;
}
.bea-dmg-kpi {
  display: flex;
  gap: 0.8rem;
  align-items: center;
  text-decoration: none;
  color: inherit;
  position: relative;
  overflow: hidden;
  background: #fff;
  border: 1px solid #dbe3ee;
  border-radius: 1rem;
  padding: 0.95rem 1rem;
  box-shadow: 0 8px 22px rgba(15, 23, 42, 0.05);
  animation: beaMgRise 0.5s ease both;
  animation-delay: calc(var(--i, 0) * 55ms);
  transition: transform 0.22s ease, box-shadow 0.22s ease, border-color 0.22s ease;
}
.bea-dmg-kpi::before {
  content: '';
  position: absolute;
  inset: 0 auto 0 0;
  width: 4px;
  background: #1a5278;
}
.bea-dmg-kpi[data-tone='warn']::before { background: #d97706; }
.bea-dmg-kpi[data-tone='danger']::before { background: #dc2626; }
.bea-dmg-kpi[data-tone='teal']::before { background: #059669; }
.bea-dmg-kpi[data-tone='blue']::before { background: #2563eb; }
.bea-dmg-kpi:hover {
  transform: translateY(-3px);
  border-color: #94a3b8;
  box-shadow: 0 14px 28px rgba(26, 82, 120, 0.12);
}
.bea-dmg-kpi[data-live][data-tone='danger'] {
  animation: beaMgRise 0.5s ease both, beaDmgPulse 2.4s ease-in-out infinite;
  animation-delay: calc(var(--i, 0) * 55ms), 0.7s;
}
.bea-dmg-kpi__icon {
  flex: 0 0 auto;
  width: 2.55rem;
  height: 2.55rem;
  border-radius: 0.75rem;
  display: grid;
  place-items: center;
  background: #e8eef5;
  color: #1a5278;
}
.bea-dmg-kpi__icon mat-icon {
  font-size: 1.25rem;
  width: 1.25rem;
  height: 1.25rem;
}
.bea-dmg-kpi__icon[data-tone='warn'] { background: #fef3c7; color: #b45309; }
.bea-dmg-kpi__icon[data-tone='danger'] { background: #fee2e2; color: #b91c1c; }
.bea-dmg-kpi__icon[data-tone='blue'] { background: #dbeafe; color: #1d4ed8; }
.bea-dmg-kpi__icon[data-tone='teal'] { background: #d1fae5; color: #047857; }
.bea-dmg-kpi[data-live] .bea-dmg-kpi__icon {
  animation: beaDmgIcon 2.4s ease-in-out infinite;
  animation-delay: 0.7s;
}
.bea-dmg-kpi__meta span {
  display: block;
  font-size: 0.7rem;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: #64748b;
  font-weight: 700;
}
.bea-dmg-kpi__meta strong {
  display: block;
  margin-top: 0.12rem;
  font-size: 1.55rem;
  line-height: 1.1;
  letter-spacing: -0.03em;
  font-variant-numeric: tabular-nums;
  color: #0f172a;
}
.bea-dmg-kpi__meta em {
  display: block;
  margin-top: 0.18rem;
  font-style: normal;
  font-size: 0.72rem;
  color: #94a3b8;
}
.bea-dmg-dash__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
}
.bea-dmg-panel {
  animation: beaMgRise 0.5s ease both;
  animation-delay: 0.35s;
}
.bea-dmg-panel .bea-mg__panel-top h2 {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
}
.bea-dmg-panel .bea-mg__panel-top h2 mat-icon {
  font-size: 1.1rem;
  width: 1.1rem;
  height: 1.1rem;
  color: #1a5278;
}
.bea-dmg-bars {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  padding: 0.9rem 1rem 1rem;
}
.bea-dmg-bar {
  animation: beaMgRise 0.45s ease both;
  animation-delay: calc(0.4s + var(--i, 0) * 60ms);
}
.bea-dmg-bar__top {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 0.3rem;
  font-size: 0.82rem;
  color: #334155;
  font-weight: 600;
}
.bea-dmg-bar__top strong {
  font-variant-numeric: tabular-nums;
  color: #1a5278;
}
.bea-dmg-bar__track {
  height: 0.45rem;
  border-radius: 999px;
  background: #e2e8f0;
  overflow: hidden;
}
.bea-dmg-bar__track i {
  display: block;
  height: 100%;
  width: 0;
  border-radius: inherit;
  background: linear-gradient(90deg, #1a5278, #3498db);
  animation: beaDmgBar 0.8s cubic-bezier(0.22, 1, 0.36, 1) both;
  animation-delay: calc(0.45s + var(--i, 0) * 70ms);
}
@keyframes beaDmgPulse {
  0%, 100% { box-shadow: 0 8px 22px rgba(15, 23, 42, 0.05); }
  50% { box-shadow: 0 10px 24px rgba(220, 38, 38, 0.16); }
}
@keyframes beaDmgIcon {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.08); }
}
@keyframes beaDmgBar {
  from { transform: scaleX(0); transform-origin: left center; }
  to { transform: scaleX(1); transform-origin: left center; }
}
@media (max-width: 1100px) {
  .bea-dmg-kpis { grid-template-columns: 1fr 1fr; }
