.bea-fx-alert__body { flex: 1; min-width: 0; }
.bea-fx-alert__body strong { font-size: 0.88rem; color: #0f172a; }
.bea-fx-alert__body p { margin: 0.15rem 0; font-size: 0.83rem; color: #334155; }
.bea-fx-alert__body small { font-size: 0.75rem; color: #64748b; }
.bea-fx-alert__actions { display: flex; flex-wrap: wrap; gap: 0.35rem; justify-content: flex-end; }

/* Rapports & paramètres */
