.bea-fx-tva__liste li { --tva-accent: #15803d; display: flex; flex-wrap: wrap; align-items: center; gap: 0.5rem; padding: 0.3rem 0.4rem 0.3rem 0.6rem; border-radius: 0.55rem; background: #f8fafc; border-left: 3px solid var(--tva-accent); font-size: 0.8rem; }
