.bea-ct-table-wrap { max-height: min(38rem, calc(100vh - 21rem)); }
.bea-pager { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 0.6rem 1rem; padding: 0.6rem 1rem; border-top: 1px solid #eef2f7; font-size: 0.82rem; color: #475569; }
.bea-pager__count strong { color: #0f172a; font-variant-numeric: tabular-nums; }
