.bea-ct-kpis8 > button { display: flex; flex-direction: column; align-items: flex-start; gap: 0.15rem; padding: 0.7rem 0.85rem; border: 1px solid #e2e8f0; border-radius: 0.9rem; background: #fff; font: inherit; text-align: left; cursor: pointer; transition: transform 0.15s ease, box-shadow 0.15s ease; }
.bea-ct-kpis8 > button:hover { transform: translateY(-2px); box-shadow: 0 6px 16px rgba(15, 23, 42, 0.08); }
.bea-ct-kpis8 > button.is-on { border-color: #1a5278; box-shadow: 0 0 0 3px rgba(26, 82, 120, 0.12); }
.bea-ct-kpis8 > button:disabled { cursor: default; transform: none; box-shadow: none; }
.bea-ct-kpis8 span { font-size: 0.7rem; font-weight: 700; text-transform: uppercase; color: #64748b; }
.bea-ct-kpis8 strong { font-size: 1.25rem; color: #0f172a; font-variant-numeric: tabular-nums; }
.bea-ct-kpis8 small { font-size: 0.72rem; color: #64748b; }
.bea-ct-kpis8 [data-tone='warn'] strong { color: #b45309; }
.bea-ct-kpis8 [data-tone='danger'] strong { color: #b91c1c; }
