.bea-fx-drawer--lg { width: min(58rem, 100vw); }
.bea-fx-drawer__actions:empty { display: none; }
.bea-dd__error { margin: 1.5rem 1.25rem; padding: 1rem; border: 1px solid #fecaca; border-radius: 0.9rem; background: #fef2f2; color: #991b1b; font-size: 0.88rem; }
