.bea-dd__alerts li { display: flex; align-items: center; gap: 0.45rem; padding: 0.5rem 0.7rem; border-radius: 0.7rem; font-size: 0.84rem; background: #fffbeb; color: #92400e; border: 1px solid #fde68a; }
.bea-dd__alerts li[data-tone='danger'] { background: #fef2f2; color: #991b1b; border-color: #fecaca; }
.bea-dd__alerts li[data-tone='ok'] { background: #ecfdf5; color: #065f46; border-color: #a7f3d0; }
.bea-dd__alerts mat-icon { width: 1.1rem; height: 1.1rem; font-size: 1.1rem; }
.bea-dd__variation { font-weight: 700; }
