.bea-pay-recap > div { padding: 0.55rem 0.7rem; border-radius: 0.75rem; background: #f8fafc; border: 1px solid #eef2f7; }
.bea-pay-recap span { display: block; font-size: 0.7rem; font-weight: 700; color: #64748b; text-transform: uppercase; }
