.bea-theme-toggle:hover { opacity: 1; background: rgb(127 127 127 / 0.14); }
.bea-theme-toggle:focus-visible { outline: 2px solid var(--bea-brand-600); outline-offset: 2px; }
.bea-theme-toggle svg { width: 1.1rem; height: 1.1rem; }
.app-shell__topbar-actions .bea-theme-toggle { color: #21618c; border-color: #93c5fd; }
.bea-admin__top-actions .bea-theme-toggle { color: var(--bea-brand-800); border-color: #93c5fd; }

/* ——— Facturation : fournisseurs, contrôles, historique ——— */
.bea-fx-kpis--4 { grid-template-columns: repeat(auto-fit, minmax(13rem, 1fr)); }
.bea-fx-inline { display: inline-flex; align-items: center; gap: 0.4rem; margin: 0; }
.bea-fx-grow { flex: 1 1 16rem; min-width: 12rem; }
.bea-fx-check { display: inline-flex; align-items: center; gap: 0.4rem; font-size: 0.84rem; font-weight: 600; color: #334155; }
.bea-fx-check input { accent-color: #1a5278; }
.bea-fx-seg { display: inline-flex; gap: 0.25rem; padding: 0.2rem; border-radius: 0.7rem; background: #eef4f9; margin-bottom: 0.7rem; }
.bea-fx-seg button { border: 0; background: transparent; border-radius: 0.55rem; padding: 0.4rem 0.7rem; font: inherit; font-size: 0.82rem; font-weight: 600; color: #475569; cursor: pointer; display: inline-flex; align-items: center; gap: 0.3rem; }
.bea-fx-seg button.is-on { background: #fff; color: #1a5278; box-shadow: 0 1px 3px rgba(15, 23, 42, 0.12); }
.bea-fx-seg--sm { margin: 0; }
.bea-fx-seg--sm button { padding: 0.25rem 0.5rem; font-size: 0.72rem; }
.bea-fx-seg button[data-etat='obligatoire'].is-on { color: #b91c1c; }
.bea-fx-seg button[data-etat='masque'].is-on { color: #64748b; }
.bea-fx-champs { display: flex; flex-direction: column; gap: 0.35rem; }
.bea-fx-champs__row { display: grid; grid-template-columns: 11rem minmax(12rem, 1fr) minmax(8rem, 1fr); gap: 0.5rem; align-items: center; }
.bea-fx-champs__nom { font-size: 0.8rem; font-weight: 600; color: #334155; }
.bea-fx-champs__lib { border: 1px solid #dbe3ee; border-radius: 0.5rem; padding: 0.35rem 0.5rem; font: inherit; font-size: 0.8rem; }
.bea-fx-champs__lib:disabled { background: #f8fafc; color: #94a3b8; }
.bea-fx-suppliers { display: grid; grid-template-columns: repeat(auto-fill, minmax(18rem, 1fr)); gap: 0.85rem; }
.bea-fx-supplier { display: flex; flex-direction: column; gap: 0.5rem; padding: 1rem 1.05rem 0.85rem; background: #fff; border: 1px solid #e8eef4; border-radius: 1rem; box-shadow: 0 1px 2px rgba(15, 23, 42, 0.04); animation: beaMgRise 0.35s ease both; animation-delay: calc(var(--i, 0) * 40ms); transition: transform 0.18s ease, box-shadow 0.18s ease; }
.bea-fx-supplier:hover { transform: translateY(-2px); box-shadow: 0 10px 24px rgba(15, 23, 42, 0.08); }
.bea-fx-supplier.is-off { opacity: 0.62; }
.bea-fx-supplier__head { display: flex; align-items: flex-start; gap: 0.65rem; }
.bea-fx-supplier__head h2 { margin: 0; font-size: 1rem; }
.bea-fx-supplier__head small { color: #64748b; font-size: 0.78rem; }
.bea-fx-supplier__head .bea-mg__icon-btn { margin-left: auto; }
.bea-fx-supplier__avatar { display: grid; place-items: center; width: 2.4rem; height: 2.4rem; border-radius: 0.7rem; background: #eef4f9; color: #1a5278; font-size: 0.78rem; font-weight: 800; letter-spacing: 0.02em; flex-shrink: 0; }
.bea-fx-supplier__stats { display: grid; grid-template-columns: 1fr 1fr; gap: 0.35rem 0.6rem; margin: 0; }
.bea-fx-supplier__stats dt { font-size: 0.7rem; font-weight: 700; color: #64748b; text-transform: uppercase; letter-spacing: 0.02em; }
.bea-fx-supplier__stats dd { margin: 0; font-weight: 700; font-variant-numeric: tabular-nums; }
.bea-fx-supplier .bea-fx-spark { height: 1.75rem; fill: none; stroke: #1a5278; stroke-width: 1.8; stroke-linejoin: round; vector-effect: non-scaling-stroke; }
.bea-fx-supplier__champs { margin: 0; font-size: 0.76rem; color: #475569; line-height: 1.4; }
.bea-fx-supplier__champs mat-icon { font-size: 0.95rem; width: 0.95rem; height: 0.95rem; vertical-align: -0.15rem; color: #1a5278; }
.bea-fx-supplier__foot { display: flex; justify-content: space-between; align-items: center; gap: 0.4rem; padding-top: 0.4rem; border-top: 1px dashed #e2e8f0; font-size: 0.78rem; }
.bea-fx-supplier__foot span { display: inline-flex; align-items: center; gap: 0.4rem; }
.bea-fx-tags span[data-tone='muted'] { background: #f1f5f9; color: #64748b; }
.bea-fx-tags span[data-tone='warn'] { background: #fff7ed; color: #c2410c; }
.bea-fx-tabs { display: flex; flex-wrap: wrap; gap: 0.4rem; margin: 0 0 0.85rem; }
.bea-fx-tab { display: inline-flex; align-items: center; gap: 0.35rem; border: 1px solid #e2e8f0; background: #fff; border-radius: 999px; padding: 0.4rem 0.75rem; font: inherit; font-size: 0.82rem; font-weight: 600; color: #475569; cursor: pointer; }
.bea-fx-tab.is-active { border-color: #1a5278; background: #eef4f9; color: #1a5278; }
.bea-fx-tab .bea-ct-badge { margin-left: 0.15rem; }
.bea-fx-bulk { display: flex; flex-wrap: wrap; align-items: center; gap: 0.5rem; margin: 0 1rem 0.7rem; padding: 0.55rem 0.75rem; border-radius: 0.7rem; background: #eef4f9; animation: beaMgRise 0.2s ease both; }
.bea-fx-col-check { width: 2rem; }
.bea-fx-ctrl-table tr.is-selected { background: #f0f9ff; }
.bea-fx-ctrl-table small.bea-fx-sub { display: block; }
.bea-fx-ctrl-actions { white-space: nowrap; text-align: right; }
.bea-fx-ctrl-actions .bea-mg__btn + .bea-mg__btn { margin-left: 0.3rem; }

/* Circuit court de la facture (fiche) */
.bea-fx-circuit { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 0.6rem; margin: 0 1.1rem 0.6rem; padding: 0.6rem 0.75rem; border: 1px solid #e8eef4; border-radius: 0.8rem; background: #f8fafc; animation: beaMgRise 0.25s ease both; }
.bea-fx-circuit__steps { display: flex; flex-wrap: wrap; align-items: center; gap: 0.25rem; margin: 0; padding: 0; list-style: none; }
.bea-fx-circuit__steps li { display: inline-flex; align-items: center; gap: 0.25rem; padding: 0.2rem 0.55rem; border-radius: 999px; font-size: 0.76rem; font-weight: 700; color: #94a3b8; background: #fff; border: 1px solid #e2e8f0; }
.bea-fx-circuit__steps li + li::before { content: ''; display: none; }
.bea-fx-circuit__steps li mat-icon { font-size: 1rem; width: 1rem; height: 1rem; }
.bea-fx-circuit__steps li[data-etat='fait'] { color: #15803d; background: #f0fdf4; border-color: #bbf7d0; }
.bea-fx-circuit__steps li[data-etat='courant'] { color: #1a5278; background: #e8f1f8; border-color: #1a5278; box-shadow: 0 0 0 2px rgba(26, 82, 120, 0.12); }
.bea-fx-circuit__steps li[data-etat='facultatif'] { color: #94a3b8; border-style: dashed; }
.bea-fx-circuit__next { display: flex; align-items: center; gap: 0.6rem; }
.bea-fx-circuit__next small { font-size: 0.75rem; color: #475569; max-width: 16rem; }
.bea-fx-circuit__next--ko { color: #b91c1c; }
.bea-fx-circuit__next--ko small { color: #b91c1c; max-width: 28rem; }
.bea-fx-verdict { display: inline-flex; align-items: center; gap: 0.25rem; font-size: 0.78rem; font-weight: 700; }
.bea-fx-verdict mat-icon { font-size: 1rem; width: 1rem; height: 1rem; }
.bea-fx-verdict[data-niveau='bloquant'] { color: #b91c1c; }
.bea-fx-verdict[data-niveau='attention'] { color: #b45309; }
.bea-fx-verdict[data-niveau='ok'] { color: #15803d; }
.bea-fx-ctrl-list { margin: 0.25rem 0 0; padding: 0; list-style: none; font-size: 0.74rem; color: #64748b; }
.bea-fx-ctrl-list li[data-niveau='bloquant'] { color: #b91c1c; }
.bea-fx-ctrl-list li[data-niveau='attention'] { color: #b45309; }
.bea-fx-row-in { animation: beaMgRise 0.28s ease both; animation-delay: calc(var(--i, 0) * 22ms); }
.bea-fx-journal { list-style: none; margin: 0.3rem 0 0; padding: 0 0 0 0.4rem; border-left: 2px solid #e2e8f0; }
.bea-fx-journal__day { margin: 0.6rem 0 0.4rem; padding: 0; border: 0; font-size: 0.74rem; font-weight: 700; color: #64748b; text-transform: uppercase; letter-spacing: 0.04em; }
.bea-fx-journal__item { position: relative; display: flex; gap: 0.7rem; padding: 0 0 0.9rem 0.7rem; }
.bea-fx-journal__dot { position: absolute; left: -1.05rem; top: 0.15rem; display: grid; place-items: center; width: 1.5rem; height: 1.5rem; border-radius: 50%; background: #eef4f9; color: #1a5278; box-shadow: 0 0 0 3px #fff; }
.bea-fx-journal__dot mat-icon { font-size: 0.95rem; width: 0.95rem; height: 0.95rem; }
.bea-fx-journal__item[data-entite='point_facturation'] .bea-fx-journal__dot { color: #0f766e; background: #ecfdf5; }
.bea-fx-journal__body { flex: 1; min-width: 0; }
.bea-fx-journal__body p { display: flex; flex-wrap: wrap; align-items: center; gap: 0.25rem 0.5rem; margin: 0; font-size: 0.86rem; }
.bea-fx-journal__body p .bea-ct-link { display: inline-flex; align-items: center; gap: 0.2rem; }
.bea-fx-journal-head { display: flex; align-items: center; justify-content: space-between; gap: 0.75rem; flex-wrap: wrap; padding: 0.75rem 1rem; border-bottom: 1px solid #eef2f7; }
.bea-fx-journal-head .bea-fx-sub { margin: 0; font-size: 0.8rem; font-weight: 600; }
.bea-fx-journal-size { display: inline-flex; align-items: center; gap: 0.4rem; font-size: 0.8rem; color: #475569; }
.bea-fx-journal-size select { border: 1px solid #dbe3ee; border-radius: 0.5rem; padding: 0.25rem 0.4rem; font: inherit; background: #fff; }
.bea-fx-journal-wrap { max-height: min(40rem, calc(100vh - 21rem)); overflow-y: auto; padding: 0.4rem 1rem 0.4rem 2rem; }
.bea-fx-journal-pager { margin: 0; padding: 0.65rem 1rem; border-top: 1px solid #eef2f7; flex-wrap: wrap; }
.bea-fx-journal-pager .bea-fx-sub { margin-right: auto; }

.bea-fx .bea-mg__table td { overflow-wrap: normal; word-break: normal; }
.bea-fx .bea-mg__table-wrap { overflow-x: auto; }
.bea-fx-table { min-width: 72rem; }
.bea-fx-table td .bea-ct-badge, .bea-fx-table td .bea-fx-code, .bea-fx-table td .bea-fx-ref, .bea-fx-table td .bea-fx-sub { white-space: nowrap; }
.bea-fx-report-table .bea-mg__table { min-width: max-content; }
.bea-fx-report-table .bea-mg__table th, .bea-fx-report-table .bea-mg__table td { white-space: nowrap; }
.bea-fx-report-table .bea-mg__table td.is-num { text-align: right; font-variant-numeric: tabular-nums; }
.bea-fx .bea-mg__panel > .bea-fx-sub { margin: 0.7rem 1rem 0.5rem; font-size: 0.8rem; font-weight: 600; }
.bea-fx-journal__body small { display: block; color: #64748b; font-size: 0.76rem; }
.bea-fx-journal__meta { display: flex; flex-direction: column; align-items: flex-end; font-size: 0.76rem; color: #64748b; white-space: nowrap; }
.bea-fx-pager { display: flex; align-items: center; justify-content: center; gap: 0.7rem; margin: 0.8rem 0 0.3rem; font-size: 0.84rem; }
@media (max-width: 720px) {
  .bea-fx-champs__row { grid-template-columns: 1fr; }
  .bea-fx-supplier__stats { grid-template-columns: 1fr 1fr; }
}

/* ——— Accueil BEA DIGITAL ——— */
.bea-plateforme__body.bea-home {
  max-width: 76rem;
  padding: 1.6rem clamp(1.25rem, 2.5vw, 2.25rem) 2rem;
}
.bea-home__head { display: flex; align-items: flex-end; justify-content: space-between; gap: 1rem; margin-bottom: 1.25rem; }
.bea-home__date { margin: 0 0 0.3rem; font-size: 0.85rem; color: var(--bea-ink-muted); }
.bea-home__title { margin: 0; font-size: 1.75rem; font-weight: 700; letter-spacing: -0.02em; color: var(--bea-ink); }
.bea-home__core {
  display: inline-flex; align-items: center; gap: 0.5rem;
  padding: 0.7rem 1.15rem; border: 1px solid var(--bea-line); border-radius: 0.7rem;
  background: var(--bea-surface-card); color: var(--bea-ink);
  font-size: 0.9rem; font-weight: 600; text-decoration: none; white-space: nowrap;
  transition: border-color 0.15s ease, translate 0.2s ease;
}
.bea-home__core:hover { border-color: var(--bea-brand-600); translate: 0 -2px; }
.bea-home__core svg { width: 1.1rem; height: 1.1rem; }
.bea-home__alert {
  display: flex; align-items: center; gap: 0.75rem;
  margin-bottom: 1.6rem; padding: 0.8rem 1.1rem; border-radius: 0.7rem;
  background: var(--bea-warn-bg); color: var(--bea-warn-ink); font-size: 0.92rem;
}
.bea-home__alert svg { width: 1.15rem; height: 1.15rem; flex-shrink: 0; }
.bea-home__alert span { flex: 1; }
.bea-home__alert a { color: inherit; font-weight: 700; text-decoration: none; white-space: nowrap; }
.bea-home__alert a:hover { text-decoration: underline; }
.bea-home__section { margin-bottom: 1.6rem; }
.bea-home__h2 { margin: 0; font-size: 1.05rem; font-weight: 700; color: var(--bea-ink); }
.bea-home__section > .bea-home__h2 { margin-bottom: 0.9rem; }
.bea-home__grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(15.5rem, 1fr)); gap: 1rem; }
.bea-home__dep {
  position: relative; display: flex; flex-direction: column; gap: 0.2rem;
  padding: 1.15rem 1.25rem 1.2rem; border: 1px solid var(--bea-line); border-radius: 0.9rem;
  background: var(--bea-surface-card); color: var(--bea-ink); text-decoration: none;
  animation: bea-espace-rise 0.4s ease both; animation-delay: calc(var(--bea-i, 0) * 35ms);
  transition: border-color 0.18s ease, translate 0.22s ease, box-shadow 0.22s ease;
}
a.bea-home__dep:hover { border-color: var(--bea-brand-600); translate: 0 -3px; box-shadow: 0 10px 24px rgb(15 23 42 / 0.1); }
a.bea-home__dep:focus-visible { outline: 2px solid var(--bea-brand-600); outline-offset: 2px; }
.bea-home__dep.is-off { opacity: 0.55; cursor: default; }
.bea-home__dep-icon {
  display: grid; place-items: center; width: 2.6rem; height: 2.6rem; margin-bottom: 0.9rem;
  border-radius: 0.6rem; background: var(--bea-chip); color: var(--bea-chip-ink);
}
.bea-home__dep-icon svg { width: 1.35rem; height: 1.35rem; }
.bea-home__dep-go { position: absolute; top: 1rem; right: 1rem; color: var(--bea-ink-muted); opacity: 0.7; transition: opacity 0.15s ease, color 0.15s ease; }
.bea-home__dep-go svg { width: 1.05rem; height: 1.05rem; }
a.bea-home__dep:hover .bea-home__dep-go { opacity: 1; color: var(--bea-brand-600); }
.bea-home__dep-title { font-size: 1rem; font-weight: 700; }
.bea-home__dep-mods { font-size: 0.86rem; color: var(--bea-ink-muted); }
.bea-home__cols { display: grid; grid-template-columns: minmax(0, 1.55fr) minmax(0, 1fr); gap: 1rem; }
.bea-home__cols.is-solo { grid-template-columns: minmax(0, 1fr); }
.bea-home__panel { padding: 1.15rem 1.25rem 1.2rem; border: 1px solid var(--bea-line); border-radius: 0.9rem; background: var(--bea-surface-card); }
.bea-home__panel-head { display: flex; align-items: center; justify-content: space-between; gap: 0.75rem; margin-bottom: 1rem; }
.bea-home__periode {
  appearance: none; padding: 0.2rem 0.4rem; border: 0; border-radius: 0.4rem;
  background: transparent; color: var(--bea-ink-muted); font: inherit; font-size: 0.86rem; text-align: right; cursor: pointer;
}
.bea-home__periode:hover, .bea-home__periode:focus-visible { background: rgb(127 127 127 / 0.12); outline: none; }
.bea-home__periode option { background: var(--bea-surface-card); color: var(--bea-ink); }
.bea-home__empty { margin: 1.5rem 0; color: var(--bea-ink-muted); font-size: 0.9rem; }
.bea-home__chart { display: flex; align-items: flex-end; gap: 0.7rem; height: 9.5rem; }
.bea-home__chart.is-dense { gap: 0.2rem; }
.bea-home__bar { position: relative; display: flex; flex-direction: column; justify-content: flex-end; flex: 1; height: 100%; min-width: 0; }
.bea-home__bar-val { margin-bottom: 0.3rem; font-size: 0.75rem; color: var(--bea-ink-muted); text-align: center; font-variant-numeric: tabular-nums; }
.bea-home__bar-fill { display: block; width: 100%; border-radius: 0.3rem 0.3rem 0 0; background: var(--bea-bar); transition: height 0.4s ease; }
.bea-home__bar.is-max .bea-home__bar-fill { background: var(--bea-bar-max); }
.bea-home__pill { padding: 0.25rem 0.75rem; border-radius: 999px; background: var(--bea-ok-bg); color: var(--bea-ok-ink); font-size: 0.82rem; font-weight: 600; white-space: nowrap; }
.bea-home__pill.is-warn { background: var(--bea-warn-bg); color: var(--bea-warn-ink); }
.bea-home__etat { margin: 0; }
.bea-home__etat > div { display: flex; align-items: center; justify-content: space-between; gap: 1rem; padding: 0.7rem 0; border-top: 1px solid var(--bea-line); }
.bea-home__etat dt { color: var(--bea-ink-muted); font-size: 0.9rem; }
.bea-home__etat dd { display: inline-flex; align-items: center; gap: 0.4rem; margin: 0; color: var(--bea-ok-ink); font-size: 0.9rem; font-weight: 600; }
.bea-home__etat dd[data-ok='false'] { color: var(--bea-danger-ink); }
.bea-home__etat dd[data-ok='null'] { color: var(--bea-ink-muted); }
.bea-home__etat dd.is-plain { color: var(--bea-ink); font-weight: 500; font-variant-numeric: tabular-nums; }
.bea-home__dot { width: 0.5rem; height: 0.5rem; border-radius: 999px; background: currentColor; }
@media (max-width: 860px) {
  .bea-home__cols { grid-template-columns: minmax(0, 1fr); }
  .bea-home__head { align-items: flex-start; flex-direction: column; }
}
@media (prefers-reduced-motion: reduce) {
  .bea-home__dep { animation: none; transition: none; }
}